      'termsContent': '1. Introduction\nWelcome to Quick Save. By accessing and using our application, you agree to comply with and be bound by the following terms and conditions. If you do not agree, please do not use the service.\n\n2. Description of Service\nQuick Save is a utility tool designed to help users download video and audio from supported platforms. We also provide professional media tools for trimming videos, converting formats, compressing files (video, image, and audio), removing audio from videos (muting), and extracting high-quality MP3 from any video file.\n\n3. User Responsibility & Copyright\nUsers are solely responsible for the media they download or edit. You must ensure you have the legal right or permission from the content owner before downloading or processing copyrighted material. Quick Save does not host any content and acts only as a technical intermediary.\n\n4. Usage Restrictions\nYou may not use this app for any illegal purposes or to facilitate copyright infringement. Commercial use of the processed content without proper authorization is strictly prohibited.\n\n5. Limitation of Liability\nQuick Save is provided \"as is\" without any warranties. We are not liable for any technical failures, data loss, or legal issues arising from your use of the application.\n\n6. Changes to Terms\nWe reserve the right to modify these terms at any time. Continued use of the app constitutes acceptance of the updated terms.',
      'privacyContent': '1. Data Collection\nYour privacy is our priority. Quick Save does not require an account, and we do not collect, store, or sell any personal information such as your name, email, or location.\n\n2. On-Device Processing\nMost features, including Video Trimming, Format Conversion, File Compression, Audio Removal, and MP3 Extraction, are processed directly on your mobile device. Your media files remain private to you and never leave your device unless you choose to share them.\n\n3. Temporary Server Usage\nWhen you download a video via a link, our server processes the request to fetch the media file. This data is processed temporarily and is not stored permanently on our servers after the download is completed.\n\n4. Permissions\nWe request access to your Photo Gallery and Internal Storage only for the purpose of saving downloaded media and allowing you to select files for editing (Trimming, Converting, Compressing, etc.).\n\n5. Third-Party Links\nOur app may contain links to external sites (like YouTube, Instagram). We are not responsible for the privacy practices or content of these third-party platforms.\n\n6. Consent\nBy using Quick Save, you consent to our Privacy Policy.\n\n7. Third-Party Services and Advertising\nWe use third-party services, such as Google AdMob, to display advertisements and monitor app performance (e.g., crash logs). These services may collect anonymous data, including your device\'s Advertising ID and IP address, to provide ads and improve app stability.',
