      'posBlurBox': 'ब्लर बॉक्स सेट करें',
      'faqQ1': 'वीडियो कैसे डाउनलोड करें?',
      'faqA1': 'किसी भी समर्थित प्लेटफ़ॉर्म से वीडियो लिंक कॉपी करें, उसे होम स्क्रीन पर पेस्ट करें और जारी रखें पर क्लिक करें।',
      'faqQ2': 'मैजिक इरेज़र का उपयोग कैसे करें?',
      'faqA2': 'एक इमेज या वीडियो अपलोड करें, वॉटरमार्क या अवांछित वस्तु पर एक बॉक्स बनाएं, और "चुने हुए क्षेत्र को मिटाएं" पर क्लिक करें।',
      'faqQ3': 'वीडियो को ट्रिम कैसे करें?',
      'faqA3': 'मीडिया टूल्स पर जाएं, ट्रिम वीडियो चुनें, अपना वीडियो अपलोड करें और उस हिस्से को चुनने के लिए स्लाइडर या कस्टम टाइमर का उपयोग करें जिसे आप रखना चाहते हैं।',
      'faqQ4': 'फ़ाइल फॉर्मेट कैसे बदलें?',
      'faqA4': 'मीडिया टूल्स से "फॉर्मेट बदलें" चुनें, ऑडियो या वीडियो में से चुनें, अपनी फ़ाइल चुनें और MP3 या MP4 जैसे टारगेट फॉर्मेट को चुनें।',
      'faqQ8': 'अपने वीडियो में वॉटरमार्क कैसे जोड़ें?',
      'faqA8': 'मीडिया टूल्स > वॉटरमार्क जोड़ें पर जाएं, अपना वीडियो चुनें, टेक्स्ट लिखें या लोगो चुनें, स्थिति चुनें और "वीडियो प्रोसेस करें" पर क्लिक करें।',
      'faqQ5': 'मेरी फाइलें कहां सेव होती हैं?',
      'faqA5': 'वीडियो और इमेज आपकी फोटो गैलरी में सेव किए जाते हैं। ऑडियो फाइलें "फ़ाइलें" ऐप में "क्विक सेव" के तहत मिल सकती हैं।',
      'faqQ6': 'क्या इसका उपयोग मुफ्त है?',
      'faqA6': 'हाँ, क्विक सेव उपयोग करने के लिए पूरी तरह से मुफ्त है!',
      'faqQ7': 'समर्थित प्लेटफार्म?',
      'faqA7': 'हम यूट्यूब, इंस्टाग्राम, टिकटॉक और फेसबुक का समर्थन करते हैं।',
      'faqQ9': 'क्या मैं किसी भी फ़ाइल को कंप्रेस कर सकता हूँ?',
      'faqA9': 'हाँ! आप गुणवत्ता बनाए रखते हुए जगह बचाने के लिए वीडियो, इमेज (JPG, PNG, WebP) और ऑडियो (MP3, WAV, आदि) को कंप्रेस कर सकते हैं।',
      'faqQ10': 'वीडियो से साउंड कैसे हटाऊं?',
      'faqA10': 'मीडिया टूल्स > ऑडियो हटाएं पर जाएं। आप अपनी गैलरी से वीडियो चुन सकते हैं या लिंक पेस्ट कर सकते हैं। ऐप आपके लिए वीडियो का म्यूट वर्जन तैयार कर देगा।',
      'faqQ11': 'क्या मैं यूट्यूब या टिकटॉक लिंक से MP3 प्राप्त कर सकता हूँ?',
      'faqA11': 'हाँ, बस "MP3 निकालें" टूल का उपयोग करें। लिंक पेस्ट करें, और ऐप केवल ऑडियो प्राप्त करेगा और उसे उच्च गुणवत्ता वाली MP3 फ़ाइल के रूप में सेव करेगा।',
      'termsContent': '1. परिचय\nक्विक सेव में आपका स्वागत है। हमारे एप्लिकेशन तक पहुँचने और उसका उपयोग करने से, आप निम्नलिखित नियमों और शर्तों का पालन करने और उनसे बंधे रहने के लिए सहमत होते हैं। यदि आप सहमत नहीं हैं, तो कृपया सेवा का उपयोग न करें।\n\n2. सेवा का विवरण\nक्विक सेव एक उपयोगी टूल है जिसे उपयोगकर्ताओं को समर्थित प्लेटफ़ॉर्म से वीडियो और ऑडियो डाउनलोड करने में मदद करने के लिए डिज़ाइन किया गया है। हम वीडियो ट्रिम करने, फॉर्मेट बदलने, फ़ाइलों (वीडियो, इमेज और ऑडियो) को कंप्रेस करने, वीडियो से ऑडियो हटाने (म्यूट करने) और किसी भी वीडियो फ़ाइल से उच्च गुणवत्ता वाले MP3 निकालने के लिए पेशेवर मीडिया टूल्स भी प्रदान करते हैं।\n\n3. उपयोगकर्ता की जिम्मेदारी और कॉपीराइट\nउपयोगकर्ता उनके द्वारा डाउनलोड या संपादित किए गए मीडिया के लिए पूरी तरह जिम्मेदार हैं। आपको यह सुनिश्चित करना चाहिए कि कॉपीराइट सामग्री डाउनलोड करने या संसाधित करने से पहले आपके पास सामग्री के मालिक से कानूनी अधिकार या अनुमति है। क्विक सेव किसी भी सामग्री की मेजबानी नहीं करता है और केवल एक तकनीकी मध्यस्थ के रूप में कार्य करता है।\n\n4. उपयोग प्रतिबंध\nआप इस ऐप का उपयोग किसी भी अवैध उद्देश्य के लिए या कॉपीराइट उल्लंघन की सुविधा के लिए नहीं कर सकते हैं। उचित प्राधिकरण के बिना संसाधित सामग्री का व्यावसायिक उपयोग सख्त वर्जित है।\n\n5. देयता की सीमा\nक्विक सेव "जैसा है" वैसा ही प्रदान किया जाता है बिना किसी वारंटी के। हम एप्लिकेशन के आपके उपयोग से उत्पन्न होने वाली किसी भी तकनीकी विफलता, डेटा हानि, या कानूनी मुद्दों के लिए उत्तरदायी नहीं हैं।\n\n6. शर्तों में बदलाव\nहम किसी भी समय इन शर्तों को संशोधित करने का अधिकार सुरक्षित रखते हैं। ऐप का निरंतर उपयोग अपडेट की गई शर्तों की स्वीकृति माना जाएगा।',
      'privacyContent': '1. डेटा संग्रह\nआपकी गोपनीयता हमारी प्राथमिकता है। क्विक सेव को अकाउंट की आवश्यकता नहीं है, और हम आपके नाम, ईमेल या स्थान जैसी कोई भी व्यक्तिगत जानकारी एकत्र, संग्रहीत या बेचते नहीं हैं।\n\n2. ऑन-डिवाइस प्रोसेसिंग\nवीडियो ट्रिमिंग, फॉर्मेट रूपांतरण, फ़ाइल कंप्रेशन, ऑडियो हटाना और MP3 निष्कर्षण सहित अधिकांश सुविधाएँ सीधे आपके मोबाइल डिवाइस पर संसाधित की जाती हैं। आपकी मीडिया फ़ाइलें आपके लिए निजी रहती हैं और जब तक आप उन्हें साझा करना नहीं चुनते, तब तक वे आपके डिवाइस को नहीं छोड़ती हैं।\n\n3. अस्थायी सर्वर उपयोग\nजब आप लिंक के माध्यम से वीडियो डाउनलोड करते हैं, तो हमारा सर्वर मीडिया फ़ाइल प्राप्त करने के अनुरोध को संसाधित करता है। यह डेटा अस्थायी रूप से संसाधित किया जाता है और डाउनलोड पूरा होने के बाद हमारे सर्वर पर स्थायी रूप से संग्रहीत नहीं किया जाता है।\n\n4. अनुमतियाँ\nहम डाउनलोड किए गए मीडिया को सहेजने और आपको संपादन (ट्रिमिंग, रूपांतरण, कंप्रेशन आदि) के लिए फ़ाइलें चुनने की अनुमति देने के उद्देश्य से ही आपकी फोटो गैलरी और आंतरिक संग्रहण तक पहुंच का अनुरोध करते हैं।\n\n5. तृतीय-पक्ष लिंक\nहमारे ऐप में बाहरी साइटों (जैसे यूट्यूब, इंस्टाग्राम) के लिंक हो सकते हैं। हम इन तृतीय-पक्ष प्लेटफार्मों की गोपनीयता प्रथाओं या सामग्री के लिए जिम्मेदार नहीं हैं।\n\n6. सहमति\nक्विक सेव का उपयोग करके, आप हमारी गोपनीयता नीति के लिए सहमति देते हैं।\n\n7. तृतीय-पक्ष सेवाएँ और विज्ञापन\nहम विज्ञापन प्रदर्शित करने और ऐप के प्रदर्शन की निगरानी करने के लिए Google AdMob जैसी तृतीय-पक्ष सेवाओं का उपयोग करते हैं। ये सेवाएँ विज्ञापन प्रदान करने और ऐप की स्थिरता में सुधार करने के लिए आपके डिवाइस के विज्ञापन आईडी सहित अनाम डेटा एकत्र कर सकती हैं।',
    },
