      'erasedSavedSuccess': 'ਸਫਲਤਾਪੂਰਵਕ ਮਿਟਾਇਆ ਗਿਆ ਅਤੇ ਗੈਲਰੀ ਵਿੱਚ ਸੇਵ ਹੋ ਗਿਆ!',
      'processingFailed': 'ਪ੍ਰੋਸੈਸਿੰਗ ਅਸਫਲ ਰਹੀ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।',
      'unsupportedFileType': 'ਅਸਮਰਥਿਤ ਫਾਈਲ ਕਿਸਮ। ਕਿਰਪਾ ਕਰਕੇ ਇੱਕ ਚਿੱਤਰ ਜਾਂ ਵੀਡੀਓ ਚੁਣੋ।',
