      'watermarkBlur': 'ਵਾਟਰਮਾਰਕ ਬਲਰ',
      'readyToErase': 'ਮਿਟਾਉਣ ਲਈ ਤਿਆਰ!',
      'eraseSelectedArea': 'ਚੋਣ ਸਾਫ਼ ਕਰੋ',
      'openGallery': 'ਗੈਲਰੀ ਖੋਲ੍ਹੋ',
      'posBlurBox': 'ਬਲਰ ਬਾਕਸ ਸੈੱਟ ਕਰੋ',
      'faqQ1': 'ਵੀਡੀਓ ਕਿਵੇਂ ਡਾਊਨਲੋਡ ਕਰੀਏ?',
      'faqA1': 'ਕਿਸੇ ਵੀ ਸਮਰਥਿਤ ਪਲੇਟਫਾਰਮ ਤੋਂ ਵੀਡੀਓ ਲਿੰਕ ਕਾਪੀ ਕਰੋ, ਇਸਨੂੰ ਹੋਮ ਸਕ੍ਰੀਨ ਤੇ ਪੇਸਟ ਕਰੋ ਅਤੇ ਜਾਰੀ ਰੱਖੋ ਤੇ ਕਲਿਕ ਕਰੋ।',
      'faqQ2': 'ਮੈਜਿਕ ਇਰੇਜ਼ਰ ਦੀ ਵਰਤੋਂ ਕਿਵੇਂ ਕਰੀਏ?',
      'faqA2': 'ਇੱਕ ਚਿੱਤਰ ਜਾਂ ਵੀਡੀਓ ਅਪਲੋਡ ਕਰੋ, ਵਾਟਰਮਾਰਕ ਜਾਂ ਅਣਚਾਹੇ ਹਿੱਸੇ ਤੇ ਇੱਕ ਬਾਕਸ ਬਣਾਓ, ਅਤੇ "ਚੁਣੇ ਹੋਏ ਹਿੱਸੇ ਨੂੰ ਮਿਟਾਓ" ਤੇ ਕਲਿਕ ਕਰੋ।',
      'faqQ3': 'ਵੀਡੀਓ ਨੂੰ ਟ੍ਰਿਮ ਕਿਵੇਂ ਕਰੀਏ?',
      'faqA3': 'ਮੀਡੀਆ ਟੂਲਸ ਤੇ ਜਾਓ, ਟ੍ਰਿਮ ਵੀਡੀਓ ਚੁਣੋ, ਆਪਣਾ ਵੀਡੀਓ ਅਪਲੋਡ ਕਰੋ ਅਤੇ ਉਹ ਹਿੱਸਾ ਚੁਣਨ ਲਈ ਸਲਾਈਡਰ ਜਾਂ ਕਸਟਮ ਟਾਈਮਰ ਦੀ ਵਰਤੋਂ ਕਰੋ ਜਿਸਨੂੰ ਤੁਸੀਂ ਰੱਖਣਾ ਚਾਹੁੰਦੇ ਹੋ।',
      'faqQ4': 'ਫਾਈਲ ਫਾਰਮੈਟ ਕਿਵੇਂ ਬਦਲੀਏ?',
      'faqA4': 'ਮੀਡੀਆ ਟੂਲਸ ਤੋਂ "ਫਾਰਮੈਟ ਬਦਲੋ" ਚੁਣੋ, ਆਡੀਓ ਜਾਂ ਵੀਡੀਓ ਵਿੱਚੋਂ ਚੁਣੋ, ਆਪਣੀ ਫਾਈਲ ਚੁਣੋ ਅਤੇ MP3 ਜਾਂ MP4 ਵਰਗੇ ਟਾਰਗੇਟ ਫਾਰਮੈਟ ਨੂੰ ਚੁਣੋ।',
      'faqQ8': 'ਆਪਣੇ ਵੀਡੀਓ ਵਿੱਚ ਵਾਟਰਮਾਰਕ ਕਿਵੇਂ ਜੋੜੀਏ?',
      'faqA8': 'ਮੀਡੀਆ ਟੂਲਸ > ਵਾਟਰਮਾਰਕ ਜੋੜੋ ਤੇ ਜਾਓ, ਆਪਣਾ ਵੀਡੀਓ ਚੁਣੋ, ਟੈਕਸਟ ਲਿਖੋ ਜਾਂ ਲੋਗੋ ਚੁਣੋ, ਸਥਿਤੀ ਚੁਣੋ ਅਤੇ "ਵੀਡੀਓ ਪ੍ਰੋਸੈਸ ਕਰੋ" ਤੇ ਕਲਿਕ ਕਰੋ।',
      'faqQ5': 'ਮੇਰੀਆਂ ਫਾਈਲਾਂ ਕਿੱਥੇ ਸੇਵ ਹੁੰਦੀਆਂ ਹਨ?',
      'faqA5': 'ਵੀਡੀਓ ਅਤੇ ਚਿੱਤਰ ਤੁਹਾਡੀ ਫੋਟੋ ਗੈਲਰੀ ਵਿੱਚ ਸੇਵ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਆਡੀਓ ਫਾਈਲਾਂ "ਫਾਈਲਾਂ" ਐਪ ਵਿੱਚ "ਕੁਵਿੱਕ ਸੇਵ" ਦੇ ਅਧੀਨ ਮਿਲ ਸਕਦੀਆਂ ਹਨ।',
      'faqQ6': 'ਕੀ ਇਹ ਵਰਤਣ ਲਈ ਮੁਫ਼ਤ ਹੈ?',
      'faqA6': 'ਹਾਂ, ਕੁਵਿੱਕ ਸੇਵ ਵਰਤਣ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮੁਫ਼ਤ ਹੈ!',
      'faqQ7': 'ਸਮਰਥਿਤ ਪਲੇਟਫਾਰਮ?',
      'faqA7': 'ਅਸੀਂ ਯੂਟਿਊਬ, ਇੰਸਟਾਗ੍ਰਾਮ, ਟਿੱਕਟੌਕ ਅਤੇ ਫੇਸਬੁੱਕ ਦਾ ਸਮਰਥਨ ਕਰਦੇ ਹਾਂ।',
      'faqQ9': 'ਕੀ ਮੈਂ ਕਿਸੇ ਵੀ ਫਾਈਲ ਨੂੰ ਕੰਪਰੈੱਸ ਕਰ ਸਕਦਾ ਹਾਂ?',
      'faqA9': 'ਹਾਂ! ਤੁਸੀਂ ਕੁਆਲਿਟੀ ਬਰਕਰਾਰ ਰੱਖਦੇ ਹੋਏ ਜਗ੍ਹਾ ਬਚਾਉਣ ਲਈ ਵੀਡੀਓ, ਚਿੱਤਰ (JPG, PNG, WebP) ਅਤੇ ਆਡੀਓ (MP3, WAV, ਆਦਿ) ਨੂੰ ਕੰਪਰੈੱਸ ਕਰ ਸਕਦੇ ਹੋ।',
      'faqQ10': 'ਵੀਡੀਓ ਤੋਂ ਆਵਾਜ਼ ਕਿਵੇਂ ਹਟਾਵਾਂ?',
      'faqA10': 'ਮੀਡੀਆ ਟੂਲਸ > ਆਡੀਓ ਹਟਾਓ ਤੇ ਜਾਓ। ਤੁਸੀਂ ਆਪਣੀ ਗੈਲਰੀ ਵਿੱਚੋਂ ਇੱਕ ਵੀਡੀਓ ਚੁਣ ਸਕਦੇ ਹੋ ਜਾਂ ਇੱਕ ਲਿੰਕ ਪੇਸਟ ਕਰ ਸਕਦੇ ਹੋ। ਐਪ ਤੁਹਾਡੇ ਲਈ ਵੀਡੀਓ ਦਾ ਮਿਊਟ ਵਰਜ਼ਨ ਤਿਆਰ ਕਰੇਗੀ।',
      'faqQ11': 'ਕੀ ਮੈਂ ਯੂਟਿਊਬ ਜਾਂ ਟਿੱਕਟੌਕ ਲਿੰਕ ਤੋਂ MP3 ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹਾਂ?',
      'faqA11': 'ਹਾਂ, ਬੱਸ "MP3 ਕੱਢੋ" ਟੂਲ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਲਿੰਕ ਪੇਸਟ ਕਰੋ, ਅਤੇ ਐਪ ਸਿਰਫ ਆਡੀਓ ਪ੍ਰਾਪਤ ਕਰੇਗੀ ਅਤੇ ਇਸਨੂੰ ਉੱਚ ਗੁਣਵੱਤਾ ਵਾਲੀ MP3 ਫਾਈਲ ਵਜੋਂ ਸੇਵ ਕਰੇਗੀ।',
      'termsContent': '1. ਜਾਣ-ਪਛਾਣ\nਕੁਵਿੱਕ ਸੇਵ ਵਿੱਚ ਤੁਹਾਡਾ ਸੁਆਗਤ ਹੈ। ਸਾਡੀ ਐਪਲੀਕੇਸ਼ਨ ਤੱਕ ਪਹੁੰਚ ਕਰਕੇ ਅਤੇ ਵਰਤ ਕੇ, ਤੁਸੀਂ ਹੇਠਾਂ ਦਿੱਤੀਆਂ ਨਿਯਮਾਂ ਅਤੇ ਸ਼ਰਤਾਂ ਦੀ ਪਾਲਣਾ ਕਰਨ ਅਤੇ ਉਹਨਾਂ ਨਾਲ ਬੱਝੇ ਰਹਿਣ ਲਈ ਸਹਿਮਤ ਹੁੰਦੇ ਹੋ। ਜੇਕਰ ਤੁਸੀਂ ਸਹਿਮਤ ਨਹੀਂ ਹੋ, ਤਾਂ ਕਿਰਪਾ ਕਰਕੇ ਸੇਵਾ ਦੀ ਵਰਤੋਂ ਨਾ ਕਰੋ।\n\n2. ਸੇਵਾ ਦਾ ਵੇਰਵਾ\nਕੁਵਿੱਕ ਸੇਵ ਇੱਕ ਉਪਯੋਗੀ ਸਾਧਨ ਹੈ ਜੋ ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਸਮਰਥਿਤ ਪਲੇਟਫਾਰਮਾਂ ਤੋਂ ਵੀਡੀਓ ਅਤੇ ਆਡੀਓ ਡਾਊਨਲੋਡ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ। ਅਸੀਂ ਵੀਡੀਓਜ਼ ਨੂੰ ਟ੍ਰਿਮ ਕਰਨ, ਫਾਰਮੈਟ ਬਦਲਣ, ਫਾਈਲਾਂ (ਵੀਡੀਓ, ਚਿੱਤਰ ਅਤੇ ਆਡੀਓ) ਨੂੰ ਕੰਪਰੈੱਸ ਕਰਨ, ਵੀਡੀਓਜ਼ ਤੋਂ ਆਡੀਓ ਹਟਾਉਣ (ਮਿਊਟ ਕਰਨ), ਅਤੇ ਕਿਸੇ ਵੀ ਵੀਡੀਓ ਫਾਈਲ ਤੋਂ ਉੱਚ ਗੁਣਵੱਤਾ ਵਾਲੀ MP3 ਕੱਢਣ ਲਈ ਪੇਸ਼ੇਵਰ ਮੀਡੀਆ ਟੂਲ ਵੀ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ।\n\n3. ਉਪਭੋਗਤਾ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਅਤੇ ਕਾਪੀਰਾਈਟ\nਉਪਭੋਗਤਾ ਆਪਣੇ ਦੁਆਰਾ ਡਾਊਨਲੋਡ ਜਾਂ ਐਡਿਟ ਕੀਤੇ ਗਏ ਮੀਡੀਆ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਜ਼ਿੰਮੇਵਾਰ ਹਨ। ਤੁਹਾਨੂੰ ਇਹ ਯਕੀਨੀ ਬਣਾਉਣਾ ਚਾਹੀਦਾ ਹੈ ਕਿ ਕਾਪੀਰਾਈਟ ਸਮੱਗਰੀ ਨੂੰ ਡਾਊਨਲੋਡ ਕਰਨ ਜਾਂ ਪ੍ਰੋਸੈਸ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਕੋਲ ਸਮੱਗਰੀ ਦੇ ਮਾਲਕ ਤੋਂ ਕਾਨੂੰਨੀ ਅਧਿਕਾਰ ਜਾਂ ਇਜਾਜ਼ਤ ਹੈ। ਕੁਵਿੱਕ ਸੇਵ ਕਿਸੇ ਵੀ ਸਮੱਗਰੀ ਦੀ ਮੇਜ਼ਬਾਨੀ ਨਹੀਂ ਕਰਦਾ ਹੈ ਅਤੇ ਸਿਰਫ਼ ਇੱਕ ਤਕਨੀਕੀ ਵਿਚੋਲੇ ਵਜੋਂ ਕੰਮ ਕਰਦਾ ਹੈ।\n\n4. ਵਰਤੋਂ ਦੀਆਂ ਪਾਬੰਦੀਆਂ\nਤੁਸੀਂ ਇਸ ਐਪ ਦੀ ਵਰਤੋਂ ਕਿਸੇ ਗੈਰ-ਕਾਨੂੰਨੀ ਉਦੇਸ਼ਾਂ ਲਈ ਜਾਂ ਕਾਪੀਰਾਈਟ ਉਲੰਘਣਾ ਦੀ ਸਹੂਲਤ ਲਈ ਨਹੀਂ ਕਰ ਸਕਦੇ ਹੋ। ਉਚਿਤ ਅਧਿਕਾਰ ਤੋਂ ਬਿਨਾਂ ਪ੍ਰੋਸੈਸ ਕੀਤੀ ਸਮੱਗਰੀ ਦੀ ਵਪਾਰਕ ਵਰਤੋਂ ਦੀ ਸਖ਼ਤ ਮਨਾਹੀ ਹੈ।\n\n5. ਦੇਣਦਾਰੀ ਦੀ ਸੀਮਾ\nਕੁਵਿੱਕ ਸੇਵ ਬਿਨਾਂ ਕਿਸੇ ਵਾਰੰਟੀ ਦੇ "ਜਿਵੇਂ ਹੈ" ਪ੍ਰਦਾਨ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਅਸੀਂ ਐਪਲੀਕੇਸ਼ਨ ਦੀ ਤੁਹਾਡੀ ਵਰਤੋਂ ਤੋਂ ਪੈਦਾ ਹੋਣ ਵਾਲੀ ਕਿਸੇ ਵੀ ਤਕਨੀਕੀ ਅਸਫਲਤਾ, ਡੇਟਾ ਦੇ ਨੁਕਸਾਨ, ਜਾਂ ਕਾਨੂੰਨੀ ਮੁੱਦਿਆਂ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂ।\n\n6. ਸ਼ਰਤਾਂ ਵਿੱਚ ਬਦਲਾਅ\nਅਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਨੂੰ ਸੋਧਣ ਦਾ ਅਧਿਕਾਰ ਰਾਖਵਾਂ ਰੱਖਦੇ ਹਾਂ। ਐਪ ਦੀ ਨਿਰੰਤਰ ਵਰਤੋਂ ਅਪਡੇਟ ਕੀਤੀਆਂ ਸ਼ਰਤਾਂ ਦੀ ਸਵੀਕ੍ਰਿਤੀ ਮੰਨੀ ਜਾਵੇਗੀ।',
      'privacyContent': '1. ਡੇਟਾ ਸੰਗ੍ਰਹਿ\nਤੁਹਾਡੀ ਪ੍ਰਾਈਵੇਸੀ ਸਾਡੀ ਤਰਜੀਹ ਹੈ। ਕੁਵਿੱਕ ਸੇਵ ਲਈ ਕਿਸੇ ਖਾਤੇ ਦੀ ਲੋੜ ਨਹੀਂ ਹੈ, ਅਤੇ ਅਸੀਂ ਤੁਹਾਡੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਜਿਵੇਂ ਕਿ ਤੁਹਾਡਾ ਨਾਮ, ਈਮੇਲ, ਜਾਂ ਸਥਾਨ ਇਕੱਠੀ, ਸਟੋਰ ਜਾਂ ਵੇਚਦੇ ਨਹੀਂ ਹਾਂ।\n\n2. ਆਨ-ਡਿਵਾਈਸ ਪ੍ਰੋਸੈਸਿੰਗ\nਵੀਡੀਓ ਟ੍ਰਿਮਿੰਗ, ਫਾਰਮੈਟ ਪਰਿਵਰਤਨ, ਫਾਈਲ ਕੰਪਰੈਸ਼ਨ, ਆਡੀਓ ਹਟਾਉਣਾ ਅਤੇ MP3 ਨਿਸ਼ਕਰਸ਼ਣ ਸਮੇਤ ਜ਼ਿਆਦਾਤਰ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਸਿੱਧੇ ਤੁਹਾਡੇ ਮੋਬਾਈਲ ਡਿਵਾਈਸ ਤੇ ਪ੍ਰੋਸੈਸ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਤੁਹਾਡੀਆਂ ਮੀਡੀਆ ਫਾਈਲਾਂ ਤੁਹਾਡੇ ਲਈ ਨਿੱਜੀ ਰਹਿੰਦੀਆਂ ਹਨ ਅਤੇ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਉਹਨਾਂ ਨੂੰ ਸਾਂਝਾ ਕਰਨਾ ਨਹੀਂ ਚੁਣਦੇ, ਉਹ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ਨੂੰ ਨਹੀਂ ਛੱਡਦੀਆਂ।\n\n3. ਅਸਥਾਈ ਸਰਵਰ ਵਰਤੋਂ\nਜਦੋਂ ਤੁਸੀਂ ਲਿੰਕ ਰਾਹੀਂ ਵੀਡੀਓ ਡਾਊਨਲੋਡ ਕਰਦੇ ਹੋ, ਤਾਂ ਸਾਡਾ ਸਰਵਰ ਮੀਡੀਆ ਫਾਈਲ ਪ੍ਰਾਪਤ ਕਰਨ ਦੀ ਬੇਨਤੀ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ। ਇਹ ਡੇਟਾ ਅਸਥਾਈ ਤੌਰ ਤੇ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਡਾਊਨਲੋਡ ਪੂਰਾ ਹੋਣ ਤੋਂ ਬਾਅਦ ਸਾਡੇ ਸਰਵਰਾਂ ਤੇ ਸਥਾਈ ਤੌਰ ਤੇ ਸਟੋਰ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।\n\n4. ਇਜਾਜ਼ਤਾਂ\nਅਸੀਂ ਡਾਊਨਲੋਡ ਕੀਤੇ ਮੀਡੀਆ ਨੂੰ ਸੇਵ ਕਰਨ ਅਤੇ ਤੁਹਾਨੂੰ ਐਡਿਟ ਕਰਨ (ਟ੍ਰਿਮਿੰਗ, ਕਨਵਰਟਿੰਗ, ਕੰਪਰੈਸ਼ਨ ਆਦਿ) ਲਈ ਫਾਈਲਾਂ ਦੀ ਚੋਣ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਦੇਣ ਦੇ ਮਕਸਦ ਲਈ ਹੀ ਤੁਹਾਡੀ ਫੋਟੋ ਗੈਲਰੀ ਅਤੇ ਅੰਦਰੂਨੀ ਸਟੋਰੇਜ ਤੱਕ ਪਹੁੰਚ ਦੀ ਬੇਨਤੀ ਕਰਦੇ ਹਾਂ।\n\n5. ਤੀਜੀ-ਧਿਰ ਦੇ ਲਿੰਕ\nਸਾਡੀ ਐਪ ਵਿੱਚ ਬਾਹਰੀ ਸਾਈਟਾਂ (ਜਿਵੇਂ YouTube, Instagram) ਦੇ ਲਿੰਕ ਹੋ ਸਕਦੇ ਹਨ। ਅਸੀਂ ਇਹਨਾਂ ਤੀਜੀ-ਧਿਰ ਦੇ ਪਲੇਟਫਾਰਮਾਂ ਦੀਆਂ ਪ੍ਰਾਈਵੇਸੀ ਅਭਿਆਸਾਂ ਜਾਂ ਸਮੱਗਰੀ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂ।\n\n6. ਸਹਿਮਤੀ\nਕੁਵਿੱਕ ਸੇਵ ਦੀ ਵਰਤੋਂ ਕਰਕੇ, ਤੁਸੀਂ ਸਾਡੀ ਪ੍ਰਾਈਵੇਸੀ ਪਾਲਿਸੀ ਲਈ ਸਹਿਮਤੀ ਦਿੰਦੇ ਹੋ।\n\n7. ਤੀਜੀ-ਧਿਰ ਦੀਆਂ ਸੇਵਾਵਾਂ ਅਤੇ ਇਸ਼ਤਿਹਾਰਬਾਜ਼ੀ\nਅਸੀਂ ਇਸ਼ਤਿਹਾਰ ਦਿਖਾਉਣ ਅਤੇ ਐਪ ਦੀ ਕਾਰਗੁਜ਼ਾਰੀ ਦੀ ਨਿਗਰਾਨੀ ਕਰਨ ਲਈ ਗੂਗਲ ਐਡਮੋਬ ਵਰਗੀਆਂ ਤੀਜੀ-ਧਿਰ ਦੀਆਂ ਸੇਵਾਵਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਾਂ। ਇਹ ਸੇਵਾਵਾਂ ਇਸ਼ਤਿਹਾਰ ਪ੍ਰਦਾਨ ਕਰਨ ਅਤੇ ਐਪ ਦੀ ਸਥਿਰਤਾ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਤੁਹਾਡੀ ਡਿਵਾਈਸ ਦੀ ਐਡਵਰਟਾਈਜ਼ਿੰਗ ਆਈਡੀ ਸਮੇਤ ਅਗਿਆਤ ਡੇਟਾ ਇਕੱਠਾ ਕਰ ਸਕਦੀਆਂ ਹਨ।',
    },
