      'posBlurBox': 'Posiciona el cuadro',
      'faqQ9': '¿Puedo comprimir cualquier archivo?',
      'faqA9': '¡Sí! Puedes comprimir videos, imágenes (JPG, PNG, WebP) y audio (MP3, WAV, etc.) para ahorrar espacio manteniendo la calidad.',
      'faqQ10': '¿Cómo elimino el sonido de un video?',
      'faqA10': 'Ve a Herramientas > Quitar Audio. Puedes elegir un video de tu galería o pegar un enlace. La aplicación generará una versión silenciada para ti.',
      'faqQ11': '¿Puedo obtener MP3 de un enlace de YouTube o TikTok?',
      'faqA11': 'Sí, simplemente usa la herramienta "Extraer MP3". Pega el enlace y la aplicación obtendrá solo el audio y lo guardará como un archivo MP3 de alta calidad.',
      'termsContent': '1. Introducción\nBienvenido a Quick Save. Al acceder y utilizar nuestra aplicación, usted acepta cumplir y estar sujeto a los siguientes términos y condiciones. Si no está de acuerdo, por favor no utilice el servicio.\n\n2. Descripción del Servicio\nQuick Save es una herramienta de utilidad diseñada para ayudar a los usuarios a descargar videos y audios de plataformas compatibles. También proporcionamos herramientas profesionales para recortar videos, convertir formatos, comprimir archivos (video, imagen y audio), eliminar el audio de los videos (silenciar) y extraer MP3 de alta calidad de cualquier archivo de video.\n\n3. Responsabilidad del Usuario y Derechos de Autor\nLos usuarios son los únicos responsables de los medios que descargan o editan. Debe asegurarse de tener el derecho legal o el permiso del propietario del contenido antes de descargar o procesar material protegido por derechos de autor. Quick Save no aloja ningún contenido y actúa solo como un intermediario técnico.\n\n4. Restricciones de Uso\nNo puede utilizar esta aplicación para fines ilegales o para facilitar la infracción de derechos de autor. El uso comercial del contenido procesado sin la debida autorización está estrictamente prohibido.\n\n5. Limitación de Responsabilidad\nQuick Save se proporciona "tal cual" sin ninguna garantía. No somos responsables de fallas técnicas, pérdida de datos o problemas legales derivados de su uso de la aplicación.\n\n6. Cambios en los Términos\nNos reservamos el derecho de modificar estos términos en cualquier momento. El uso continuado de la aplicación constituye la aceptación de los términos actualizados.',
      'privacyContent': '1. Recopilación de Datos\nSu privacidad es nuestra prioridad. Quick Save no requiere una cuenta y no recopilamos, almacenamos ni vendemos ninguna información personal como su nombre, correo electrónico o ubicación.\n\n2. Procesamiento en el Dispositivo\nLa mayoría de las funciones, incluido el recorte de video, la conversión de formato, la compresión de archivos, la eliminación de audio y la extracción de MP3, se procesan directamente en su dispositivo móvil. Sus archivos multimedia siguen siendo privados y nunca salen de su dispositivo a menos que elija compartirlos.\n\n3. Uso Temporal del Servidor\nCuando descarga un video a través de un enlace, nuestro servidor procesa la solicitud para obtener el archivo multimedia. Estos datos se procesan temporalmente y no se almacenan permanentemente en nuestros servidores una vez finalizada la descarga.\n\n4. Permisos\nSolicitamos acceso a su Galería de Fotos y Almacenamiento Interno solo con el fin de guardar los medios descargados y permitirle seleccionar archivos para editarlos (recortar, convertir, comprimir, etc.).\n\n5. Enlaces de Terceros\nNuestra aplicación puede contener enlaces a sitios externos (como YouTube, Instagram). No somos responsables de las prácticas de privacidad o el contenido de estas plataformas de terceros.\n\n6. Consentimiento\nAl usar Quick Save, usted acepta nuestra Política de Privacidad.\n\n7. Servicios de terceros y publicidad\nUtilizamos servicios de terceros, como Google AdMob, para mostrar anuncios y monitorear el rendimiento de la aplicación. Estos servicios pueden recopilar datos anónimos, incluido el ID de publicidad de su dispositivo, para proporcionar anuncios y mejorar la estabilidad de la aplicación.',
    },
