      'watermarkBlur': 'Flou Filigrane',
      'readyToErase': 'Prêt à effacer !',
      'eraseSelectedArea': 'EFFACER SÉLECTION',
      'openGallery': 'GALERIE',
      'posBlurBox': 'Positionnez le flou',
      'faqQ1': 'Comment télécharger ?',
      'faqA1': 'Copiez le lien, collez-le sur l\'accueil et cliquez sur continuer.',
      'faqQ2': 'Gomme Magique ?',
