      'faqA8': 'Outils > Filigrane, entrez le texte ou logo, choisissez la position.',
      'faqQ5': 'Où sont les fichiers ?',
      'faqA5': 'Vidéos/images dans la Galerie. Audios dans "Files" > "Quick Save".',
      'faqQ6': 'Est-ce gratuit ?',
      'faqA6': 'Oui, Quick Save est totalement gratuit !',
      'faqQ7': 'Plateformes supportées ?',
      'faqA7': 'YouTube, Instagram, TikTok et Facebook.',
      'faqQ9': 'Puis-je compresser n\'importe quel fichier ?',
      'faqA9': 'Oui ! Vous pouvez compresser des vidéos, des images (JPG, PNG, WebP) et de l\'audio (MP3, WAV, etc.) pour gagner de l\'espace tout en conservant la qualité.',
      'faqQ10': 'Comment supprimer le son d\'une vidéo ?',
      'faqA10': 'Allez dans Outils Média > Supprimer l\'audio. Vous pouvez choisir une vidéo dans votre galerie ou coller un lien. L\'application générera une version muette pour vous.',
      'faqQ11': 'Puis-je obtenir un MP3 à partir d\'un lien YouTube ou TikTok ?',
      'faqA11': 'Oui, utilisez simplement l\'outil "Extraire MP3". Collez le lien, et l\'application récupérera uniquement l\'audio et l\'enregistrera en tant que fichier MP3 de haute qualité.',
      'termsContent': '1. Introduction\nBienvenue sur Quick Save. En accédant à notre application et en l\'utilisant, vous acceptez de vous conformer aux termes et conditions suivants. Si vous n\'êtes pas d\'accord, veuillez ne pas utiliser le service.\n\n2. Description du service\nQuick Save est un outil conçu pour aider les utilisateurs à télécharger des vidéos et de l\'audio à partir de plateformes prises en charge. Nous proposons également des outils professionnels pour couper des vidéos, convertir des formats, compresser des fichiers (vidéo, image et audio), supprimer l\'audio des vidéos (muet) et extraire des MP3 de haute qualité à partir de n\'importe quel fichier vidéo.\n\n3. Responsabilité de l\'utilisateur et droits d\'auteur\nLes utilisateurs sont seuls responsables des médias qu\'ils téléchargent ou modifient. Vous devez vous assurer que vous disposez du droit légal ou de l\'autorisation du propriétaire du contenu avant de télécharger ou de traiter du matériel protégé par le droit d\'auteur. Quick Save n\'héberge aucun contenu et agit uniquement en tant qu\'intermédiaire technique.\n\n4. Restrictions d\'utilisation\nVous ne pouvez pas utiliser cette application à des fins illégales ou pour faciliter la violation des droits d\'auteur. L\'utilisation commerciale du contenu traité sans autorisation appropriée est strictement interdite.\n\n5. Limitation de responsabilité\nQuick Save est fourni "tel quel" sans aucune garantie. Nous ne sommes pas responsables des défaillances techniques, de la perte de données ou des problèmes juridiques découlant de votre utilisation de l\'application.\n\n6. Modification des conditions\nNous nous réservons le droit de modifier ces conditions à tout moment. L\'utilisation continue de l\'application constitue l\'acceptation des conditions mises à jour.',
      'privacyContent': '1. Collecte de données\nVotre vie privée est notre priorité. Quick Save ne nécessite pas de compte et nous ne collectons, ne stockons ni ne vendons aucune information personnelle telle que votre nom, votre e-mail ou votre emplacement.\n\n2. Traitement sur l\'appareil\nLa plupart des fonctionnalités, notamment le découpage vidéo, la conversion de format, la compression de fichiers, la suppression de l\'audio et l\'extraction de MP3, sont traitées directement sur votre appareil mobile. Vos fichiers multimédias restent privés et ne quittent jamais votre appareil à moins que vous ne choisissiez de les partager.\n\n3. Utilisation temporaire du serveur\nLorsque vous téléchargez une vidéo via un lien, notre serveur traite la demande pour récupérer le fichier multimédia. Ces données sont traitées temporairement et ne sont pas stockées de manière permanente sur nos serveurs une fois le téléchargement terminé.\n\n4. Autorisations\nNous demandons l\'accès à votre galerie de photos et à votre stockage interne uniquement dans le but d\'enregistrer les médias téléchargés et de vous permettre de sélectionner des fichiers pour les éditer (couper, convertir, compresser, etc.).\n\n5. Liens tiers\nNotre application peut contenir des liens vers des sites externes (comme YouTube, Instagram). Nous ne sommes pas responsables des pratiques de confidentialité ou du contenu de ces plateformes tierces.\n\n6. Consentement\nEn utilisant Quick Save, vous consentez à notre politique de confidentialité.\n\n7. Services tiers et publicité\nNous utilisons des services tiers, tels que Google AdMob, pour afficher des publicités et surveiller les performances de l\'application. Ces services peuvent collecter des données anonymes, y compris l\'identifiant publicitaire de votre appareil, pour fournir des publicités et améliorer la stabilité de l\'application.',
    },
