      'faqQ5': 'Wo sind meine Dateien?',
      'faqA5': 'Videos in der Galerie. Audio in "Dateien" > "Quick Save".',
      'faqQ6': 'Kostenlos?',
      'faqA6': 'Ja, Quick Save ist völlig kostenlos!',
      'faqQ7': 'Unterstützte Plattformen?',
      'faqA7': 'YouTube, Instagram, TikTok und Facebook.',
      'faqQ9': 'Kann ich jede Datei komprimieren?',
      'faqA9': 'Ja! Sie können Videos, Bilder (JPG, PNG, WebP) und Audio (MP3, WAV usw.) komprimieren, um Platz zu sparen und gleichzeitig die Qualität beizubehalten.',
      'faqQ10': 'Wie entferne ich den Ton aus einem Video?',
      'faqA10': 'Gehen Sie zu Medien-Werkzeuge > Audio entfernen. Sie können entweder ein Video aus Ihrer Galerie auswählen oder einen Link einfügen. Die App erstellt eine stummgeschaltete Version des Videos für Sie.',
      'faqQ11': 'Kann ich MP3 von einem YouTube- oder TikTok-Link erhalten?',
      'faqA11': 'Ja, verwenden Sie einfach das Werkzeug "MP3 extrahieren". Fügen Sie den Link ein, und die App ruft nur das Audio ab und speichert es als hochwertige MP3-Datei.',
      'termsContent': '1. Einführung\nWillkommen bei Quick Save. Durch den Zugriff auf unsere Anwendung und deren Nutzung erklären Sie sich mit den folgenden Geschäftsbedingungen einverstanden. Wenn Sie nicht einverstanden sind, nutzen Sie den Dienst bitte nicht.\n\n2. Beschreibung des Dienstes\nQuick Save ist ein Hilfsprogramm, das Benutzern hilft, Videos und Audio von unterstützten Plattformen herunterzuladen. Wir bieten auch professionelle Medien-Werkzeuge zum Schneiden von Videos, Konvertieren von Formaten, Komprimieren von Dateien (Video, Bild und Audio), Entfernen von Audio aus Videos (Stummschalten) und Extrahieren von hochwertigem MP3 aus jeder Videodatei.\n\n3. Benutzerverantwortung & Urheberrecht\nBenutzer sind allein für die von ihnen heruntergeladenen oder bearbeiteten Medien verantwortlich. Sie müssen sicherstellen, dass Sie das gesetzliche Recht oder die Erlaubnis des Eigentümers des Inhalts haben, bevor Sie urheberrechtlich geschütztes Material herunterladen oder verarbeiten. Quick Save hostet keine Inhalte und fungiert nur als technischer Vermittler.\n\n4. Nutzungsbeschränkungen\nSie dürfen diese App nicht für illegale Zwecke oder zur Erleichterung von Urheberrechtsverletzungen verwenden. Die gewerbliche Nutzung der verarbeiteten Inhalte ohne entsprechende Genehmigung ist strengstens untersagt.\n\n5. Haftungsbeschränkung\nQuick Save wird "wie besehen" ohne jegliche Gewährleistung bereitgestellt. Wir haften nicht für technische Ausfälle, Datenverluste oder rechtliche Probleme, die sich aus Ihrer Nutzung der Anwendung ergeben.\n\n6. Änderungen der Bedingungen\nWir behalten uns das Recht vor, diese Bedingungen jederzeit zu ändern. Die fortgesetzte Nutzung der App gilt als Annahme der aktualisierten Bedingungen.',
      'privacyContent': '1. Datenerhebung\nIhre Privatsphäre ist unsere Priorität. Quick Save erfordert kein Konto und wir erheben, speichern oder verkaufen keine persönlichen Informationen wie Ihren Namen, Ihre E-Mail-Adresse oder Ihren Standort.\n\n2. Verarbeitung auf dem Gerät\nDie meisten Funktionen, einschließlich Videoschnitt, Formatkonvertierung, Dateikomprimierung, Audioentfernung und MP3-Extraktion, werden direkt auf Ihrem Mobilgerät verarbeitet. Ihre Mediendateien bleiben privat und verlassen Ihr Gerät nie, es sei denn, Sie entscheiden sich, sie zu teilen.\n\n3. Temporäre Servernutzung\nWenn Sie ein Video über einen Link herunterladen, verarbeitet unser Server die Anfrage zum Abrufen der Mediendatei. Diese Daten werden vorübergehend verarbeitet und nach Abschluss des Downloads nicht dauerhaft auf unseren Servern gespeichert.\n\n4. Berechtigungen\nWir fordern Zugriff auf Ihre Fotogalerie und Ihren internen Speicher nur zum Zwecke des Speicherns heruntergeladener Medien und zur Auswahl von Dateien zur Bearbeitung (Schneiden, Konvertieren, Komprimieren usw.) an.\n\n5. Links von Drittanbietern\nUnsere App kann Links zu externen Websites (wie YouTube, Instagram) enthalten. Wir sind nicht verantwortlich für die Datenschutzpraktiken oder den Inhalt dieser Drittplattformen.\n\n6. Zustimmung\nDurch die Nutzung von Quick Save stimmen Sie unserer Datenschutzrichtlinie zu.\n\n7. Dienste von Drittanbietern und Werbung\nWir verwenden Dienste von Drittanbietern wie Google AdMob, um Werbung anzuzeigen und die App-Leistung zu überwachen. Diese Dienste können anonyme Daten erfassen, einschließlich der Werbe-ID Ihres Geräts, um Anzeigen bereitzustellen und die App-Stabilität zu verbessern.',
    },
