      'faqQ9': '我可以压缩任何文件吗？',
      'faqA9': '是的！您可以压缩视频、图像（JPG、PNG、WebP）和音频（MP3、WAV 等），在保持质量的同时节省空间。',
      'faqQ10': '如何从视频中删除声音？',
      'faqA10': '转到媒体工具 > 移除音频。您可以从相册中选择视频或粘贴链接。应用程序将为您生成视频的静音版本。',
      'faqQ11': '我可以从 YouTube 或 TikTok 链接获取 MP3 吗？',
      'faqA11': '是的，只需使用“提取 MP3”工具。粘贴链接，应用程序将仅获取音频并将其保存为高质量的 MP3 文件。',
      'termsContent': '1. 简介\n欢迎使用 Quick Save。访问和使用我们的应用程序，即表示您同意遵守并受以下条款和条件的约束。如果您不同意，请不要使用该服务。\n\n2. 服务描述\nQuick Save 是一款实用工具，旨在帮助用户从支持的平台下载视频和音频。我们还提供专业的媒体工具，用于修剪视频、转换格式、压缩文件（视频、图像和音频）、从视频中移除音频（静音）以及从任何视频文件中提取高质量的 MP3。\n\n3. 用户责任与版权\n用户对其下载或编辑的媒体负全部责任。在下载或处理受版权保护的材料之前，您必须确保拥有内容所有者的合法权利或许可。Quick Save 不托管任何内容，仅作为技术中介。\n\n4. 使用限制\n您不得将此应用程序用于任何非法目的或协助侵犯版权。严禁在未经适当授权的情况下将处理后的内容用于商业用途。\n\n5. 责任限制\nQuick Save 按“原样”提供，不作任何保证。对于因您使用应用程序而产生的任何技术故障、数据丢失或法律问题， we 概不负责。\n\n6. 条款变更\n我们保留随时修改这些条款的权利。继续使用该应用程序即表示接受更新后的条款。',
      'privacyContent': '1. 数据收集\n您的隐私是我们的首要任务。Quick Save 不需要账户，我们不会收集、存储或出售您的姓名、电子邮件或位置等任何个人信息。\n\n2. 设备端处理\n大多数功能（包括视频修剪、格式转换、文件压缩、音频移除和 MP3 提取）都在您的移动设备上直接处理。您的媒体文件对您而言保持私密，除非您选择共享，否则绝不会离开您的设备。\n\n3. 临时服务器使用\n当您通过链接下载视频时，我们的服务器会处理获取媒体文件的请求。此数据仅作临时处理，下载完成后不会永久存储在我们的服务器上。\n\n4. 权限\n我们请求访问您的照片库和内部存储空间，仅用于保存下载的媒体以及允许您选择要编辑的文件（修剪、转换、压缩等）。\n\n5. 第三方链接\n我们的应用程序可能包含指向外部网站（如 YouTube、Instagram）的链接。我们对这些第三方平台的隐私惯例或内容不承担任何责任。\n\n6. 同意\n使用 Quick Save 即表示您同意我们的隐私政策。\n\n7. 第三方服务和广告\n我们使用第三方服务（例如 Google AdMob）来显示广告并监控应用性能。这些服务可能会收集匿名数据（包括您设备的广告 ID），以提供广告并提高应用稳定性。',
    },
