      'faqQ1': 'كيف أحمل فيديو؟',
      'faqA1': 'انسخ الرابط، الصقه في الشاشة الرئيسية، واضغط متابعة.',
      'faqQ2': 'كيف أستخدم الممحاة السحرية؟',
