      'faqA3': 'من أدوات الميديا، اختر قص، ارفع الفيديو وحدد الجزء المطلوب.',
      'faqQ4': 'كيف أحول التنسيق؟',
      'faqA4': 'اختر "تحويل التنسيق"، اختر النوع، حدد الملف ثم التنسيق الهدف.',
      'faqQ8': 'كيف أضيف علامة مائية؟',
      'faqA8': 'أدوات الميديا > إضافة علامة، اختر الفيديو، اكتب النص أو الشعار.',
      'faqQ5': 'أين تحفظ الملفات؟',
      'faqA5': 'الفيديو في المعرض، والصوت في مجلد "Quick Save" في ملفاتك.',
      'faqQ6': 'هل هو مجاني؟',
      'faqA6': 'نعم، التطبيق مجاني تماماً!',
      'faqQ7': 'المنصات المدعومة؟',
      'faqA7': 'يوتيوب، إنستغرام، تيك توك، وفيسبوك.',
      'faqQ9': 'هل يمكنني ضغط أي ملف؟',
      'faqA9': 'نعم! يمكنك ضغط مقاطع الفيديو والصور (JPG, PNG, WebP) والصوت (MP3, WAV, إلخ) لتوفير المساحة مع الحفاظ على الجودة.',
      'faqQ10': 'كيف أحذف الصوت من الفيديو؟',
      'faqA10': 'انتقل إلى أدوات الميديا > إزالة الصوت. يمكنك اختيار فيديو من معرض الصور الخاص بك أو لصق رابط. سيقوم التطبيق بإنشاء نسخة صامتة من الفيديو لك.',
      'faqQ11': 'هل يمكنني الحصول على MP3 من رابط يوتيوب أو تيك توك؟',
      'faqA11': 'نعم، ما عليك سوى استخدام أداة "استخراج MP3". الصق الرابط، وسيقوم التطبيق بجلب الصوت فقط وحفظه كملف MP3 عالي الجودة.',
      'termsContent': '1. مقدمة\nمرحبًا بك في Quick Save. من خلال الوصول إلى تطبيقنا واستخدامه، فإنك توافق على الامتثال للشروط والأحكام التالية والالتزام بها. إذا كنت لا توافق، فيرجى عدم استخدام الخدمة.\n\n2. وصف الخدمة\nQuick Save هي أداة مساعدة مصممة لمساعدة المستخدمين على تنزيل الفيديو والصوت من المنصات المدعومة. نوفر أيضًا أدوات ميديا احترافية لقص الفيديوهات، وتحويل التنسيقات، وضغط الملفات (فيديو، صورة، وصوت)، وإزالة الصوت من الفيديوهات (كتم الصوت)، واستخراج MP3 عالي الجودة من أي ملف فيديو.\n\n3. مسؤولية المستخدم وحقوق الطبع والنشر\nالمستخدمون مسؤولون وحدهم عن الوسائط التي يقومون بتنزيلها أو تحريرها. يجب عليك التأكد من حصولك على الحق القانوني أو الإذن من مالك المحتوى قبل تنزيل أو معالجة المواد المحمية بحقوق الطبع والنشر. لا يستضيف Quick Save أي محتوى ويعمل فقط كوسيط تقني.\n\n4. قيود الاستخدام\nلا يجوز لك استخدام هذا التطبيق لأي أغراض غير قانونية أو لتسهيل انتهاك حقوق الطبع والنشر. يمنع منعًا باتًا الاستخدام التجاري للمحتوى الذي تمت معالجته دون تصريح مناسب.\n\n5. تحديد المسؤولية\nيتم تقديم Quick Save "كما هو" دون أي ضمانات. نحن لسنا مسؤولين عن أي إخفاقات فنية أو فقدان بيانات أو مشكلات قانونية تنشأ عن استخدامك للتطبيق.\n\n6. تغييرات الشروط\nنحتفظ بالحق في تعديل هذه الشروط في أي وقت. يعتبر الاستمرار في استخدام التطبيق قبولاً للشروط المحدثة.',
      'privacyContent': '1. جمع البيانات\nخصوصيتك هي أولويتنا. لا يتطلب Quick Save حسابًا، ونحن لا نجمع أو نخزن أو نبيع أي معلومات شخصية مثل اسمك أو بريدك الإلكتروني أو موقعك.\n\n2. معالجة البيانات على الجهاز\nتتم معالجة معظم الميزات، بما في ذلك قص الفيديو وتحويل التنسيق وضغط الملفات وإزالة الصوت واستخراج MP3، مباشرة على جهازك المحمول. تظل ملفات الوسائط الخاصة بك خاصة بك ولا تغادر جهازك أبدًا إلا إذا اخترت مشاركتها.\n\n3. استخدام الخادم المؤقت\nعند تنزيل فيديو عبر رابط، يقوم خادمنا بمعالجة الطلب لجلب ملف الوسائط. يتم معالجة هذه البيانات مؤقتًا ولا يتم تخزينها بشكل دائم على خوادمنا بعد اكتمال التنزيل.\n\n4. الأذونات\nنطلب الوصول إلى معرض الصور والتخزين الداخلي فقط لغرض حفظ الوسائط التي تم تنزيلها والسماح لك بتحديد الملفات للتحرير (القص، التحويل، الضغط، إلخ).\n\n5. روابط الطرف الثالث\nقد يحتوي تطبيقنا على روابط لمواقع خارجية (مثل YouTube وInstagram). نحن لسنا مسؤولين عن ممارسات الخصوصية أو محتوى هذه المنصات التابعة لأطراف ثالثة.\n\n6. الموافقة\nباستخدام Quick Save، فإنك توافق على سياسة الخصوصية الخاصة بنا.\n\n7. خدمات الطرف الثالث والإعلانات\nنحن نستخدم خدمات الطرف الثالث، مثل Google AdMob، لعرض الإعلانات ومراقبة أداء التطبيق. قد تقوم هذه الخدمات بجمع بيانات مجهولة المصدر، بما في ذلك المعرّف الإعلاني لجهازك، لتوفير الإعلانات وتحسين استقرار التطبيق.',
    },
