      'faqQ10': 'Como eu removo o som de um vídeo?',
      'faqA10': 'Vá em Ferramentas > Remover Áudio. Você pode escolher um vídeo da sua galeria ou colar um link. O aplicativo gerará uma versão sem áudio para você.',
      'faqQ11': 'Posso obter MP3 a partir de um link do YouTube ou TikTok?',
      'faqA11': 'Sim, basta usar a ferramenta "Extrair MP3". Cole o link e o aplicativo buscará apenas o áudio e o salvará como um arquivo MP3 de alta qualidade.',
      'termsContent': '1. Introdução\nBem-vindo ao Quick Save. Ao aceder e utilizar a nossa aplicação, concorda em cumprir e vincular-se aos seguintes termos e condições. Se não concordar, não utilize o serviço.\n\n2. Descrição do Serviço\nO Quick Save é uma ferramenta utilitária concebida para ajudar os utilizadores a descarregar vídeo e áudio de plataformas suportadas. Também fornecemos ferramentas profissionais para cortar vídeos, converter formatos, comprimir ficheiros (vídeo, imagem e áudio), remover áudio de vídeos (silenciar) e extrair MP3 de alta qualidade de qualquer ficheiro de vídeo.\n\n3. Responsabilidade do Utilizador e Direitos de Autor\nOs utilizadores são os únicos responsáveis pelos conteúdos que descarregam ou editam. Deve garantir que possui o direito legal ou permissão do proprietário do conteúdo antes de descarregar ou processar material protegido por direitos de autor. O Quick Save não aloja qualquer conteúdo e atua apenas como um intermediário técnico.\n\n4. Restrições de Utilização\nNão pode utilizar esta aplicação para fins ilegais ou para facilitar a infração de direitos de autor. O uso comercial do conteúdo processado sem a devida autorização é estritamente proibido.\n\n5. Limitação de Responsabilidade\nO Quick Save é fornecido "tal como está", sem quaisquer garantias. Não somos responsáveis por quaisquer falhas técnicas, perda de dados ou problemas legais resultantes da sua utilização da aplicação.\n\n6. Alterações aos Termos\nReservamo-nos o direito de modificar estes termos a qualquer momento. A utilização continuada da aplicação constitui a aceitação dos termos atualizados.',
      'privacyContent': '1. Recolha de Dados\nA sua privacidade é a nossa prioridade. O Quick Save não requer uma conta e não recolhemos, armazenamos ou vendemos qualquer informação pessoal, como o seu nome, e-mail ou localização.\n\n2. Processamento no Dispositivo\nA maioria das funcionalidades, incluindo o Corte de Vídeo, Conversão de Formato, Compressão de Ficheiros, Remoção de Áudio e Extração de MP3, são processadas diretamente no seu dispositivo móvel. Os seus ficheiros de média permanecem privados e nunca saem do seu dispositivo, a menos que opte por partilhá-los.\n\n3. Utilização Temporária do Servidor\nQuando descarrega um vídeo através de um link, o nosso servidor processa o pedido para obter o ficheiro de média. Estes dados são processados temporariamente e não são armazenados permanentemente nos nossos servidores após a conclusão do download.\n\n4. Permissões\nSolicitamos acesso à sua Galeria de Fotos e Armazenamento Interno apenas para fins de guardar média descarregada e permitir-lhe selecionar ficheiros para edição (Corte, Conversão, Compressão, etc.).\n\n5. Links de Terceiros\nA nossa aplicação pode conter links para sites externos (como YouTube, Instagram). Não somos responsáveis pelas práticas de privacidade ou conteúdo destas plataformas de terceiros.\n\n6. Consentimento\nAo utilizar o Quick Save, concorda com a nossa Política de Privacidade.\n\n7. Serviços de Terceiros e Publicidade\nUsamos serviços de terceiros, como o Google AdMob, para exibir anúncios e monitorar o desempenho do aplicativo. Esses serviços podem coletar dados anônimos, incluindo o ID de publicidade do seu dispositivo, para fornecer anúncios e melhorar a estabilidade do aplicativo.',
    },
