      'openGallery': 'ОТКРЫТЬ ГАЛЕРЕЮ',
      'posBlurBox': 'Расположите область размытия',
      'faqQ1': 'Как скачать видео?',
      'faqA1': 'Скопируйте ссылку на видео с любой поддерживаемой платформы, вставьте ее на главном экране и нажмите продолжить.',
      'faqQ2': 'Как использовать Волшебный ластик?',
      'faqA2': 'Загрузите изображение или видео, нарисуйте рамку над водяным знаком или нежелательным элементом и нажмите "Стереть выбранную область".',
      'faqQ3': 'Как обрезать видео?',
      'faqA3': 'Перейдите в Медиа инструменты, выберите "Обрезать видео", загрузите видео и используйте ползунок или таймер для выбора нужной части.',
      'faqQ4': 'Как изменить формат файла?',
      'faqA4': 'Выберите "Конвертировать формат" в Медиа инструментах, выберите Аудио или Видео, выберите файл и выберите целевой формат, например MP3 или MP4.',
      'faqQ8': 'Как добавить водяной знак к видео?',
      'faqA8': 'Перейдите в Медиа инструменты > Добавить водяной знак, выберите видео, введите текст или выберите логотип, выберите позицию и нажмите "Обработать видео".',
      'faqQ5': 'Где сохраняются мои файлы?',
      'faqA5': 'Видео и изображения сохраняются в вашу Фотогалерею. Аудиофайлы можно найти в приложении "Файлы" в папке "Quick Save".',
      'faqQ6': 'Это бесплатно?',
      'faqA6': 'Да, Quick Save полностью бесплатен!',
      'faqQ7': 'Поддерживаемые платформы?',
      'faqA7': 'Мы поддерживаем YouTube, Instagram, TikTok и Facebook.',
      'faqQ9': 'Могу ли я сжать любой файл?',
      'faqA9': 'Да! Вы можете сжимать видео, изображения (JPG, PNG, WebP) и аудио (MP3, WAV и т. д.), чтобы сэкономить место при сохранении качества.',
      'faqQ10': 'Как удалить звук из видео?',
      'faqA10': 'Перейдите в Медиа инструменты > Удалить аудио. Вы можете выбрать видео из галереи или вставить ссылку. Приложение создаст для вас версию видео без звука.',
      'faqQ11': 'Могу ли я получить MP3 по ссылке из YouTube или TikTok?',
      'faqA11': 'Да, просто используйте инструмент "Извлечь MP3". Вставьте ссылку, и приложение загрузит только аудио и сохранит его как высококачественный MP3-файл.',
      'termsContent': '1. Введение\nДобро пожаловать в Quick Save. Получая доступ к нашему приложению и используя его, вы соглашаетесь соблюдать следующие положения и условия. Если вы не согласны, пожалуйста, не используйте сервис.\n\n2. Описание услуги\nQuick Save — это служебный инструмент, разработанный, чтобы помочь пользователям загружать видео и аудио с поддерживаемых платформ. Мы также предоставляем профессиональные медиа инструменты для обрезки видео, конвертации форматов, сжатия файлов (видео, изображений и аудио), удаления звука из видео (выключения звука) и извлечения высококачественного MP3 из любого видеофайла.\n\n3. Ответственность пользователя и авторские права\nПользователи несут единоличную ответственность за медиафайлы, которые они загружают или редактируют. Вы должны убедиться, что у вас есть законное право или разрешение от владельца контента, прежде чем загружать или обрабатывать материалы, защищенные авторским правом. Quick Save не размещает никакого контента и выступает только в качестве технического посредника.\n\n4. Ограничения на использование\nВы не можете использовать это приложение в каких-либо незаконных целях или для содействия нарушению авторских прав. Коммерческое использование обработанного контента без соответствующего разрешения строго запрещено.\n\n5. Ограничение ответственности\nQuick Save предоставляется "как есть" без каких-либо гарантий. Мы не несем ответственности за любые технические сбои, потерю данных или юридические проблемы, возникающие в результате использования вами приложения.\n\n6. Изменения в условиях\nМы оставляем за собой право изменять эти условия в любое время. Продолжение использования приложения означает согласие с обновленными условиями.',
      'privacyContent': '1. Сбор данных\nВаша конфиденциальность является нашим приоритетом. Quick Save не требует создания учетной записи, и мы не собираем, не храним и не продаем никакую личную информацию, такую как ваше имя, адрес электронной почты или местоположение.\n\n2. Обработка на устройстве\nБольшинство функций, включая обрезку видео, преобразование формата, сжатие файлов, удаление звука и извлечение MP3, обрабатываются непосредственно на вашем мобильном устройстве. Ваши медиафайлы остаются конфиденциальными и никогда не покидают ваше устройство, если только вы не решите ими поделиться.\n\n3. Временное использование сервера\nКогда вы загружаете видео по ссылке, наш сервер обрабатывает запрос на получение медиафайла. Эти данные обрабатываются временно и не хранятся постоянно на наших серверах после завершения загрузки.\n\n4. Разрешения\nМы запрашиваем доступ к вашей фотогалерее и внутреннему хранилищу только в целях сохранения загруженного контента и предоставления вам возможности выбирать файлы для редактирования (обрезка, конвертация, сжатие и т. д.).\n\n5. Ссылки на сторонние ресурсы\nНаше приложение может содержать ссылки на внешние сайты (например, YouTube, Instagram). Мы не несем ответственности за политику конфиденциальности или контент этих сторонних платформ.\n\n6. Согласие\nИспользуя Quick Save, вы соглашаетесь с нашей Политикой конфиденциальности.\n\n7. Сторонние сервисы и реклама\nМы используем сторонние сервисы, такие как Google AdMob, для показа рекламы и мониторинга производительности приложения. Эти сервисы могут собирать анонимные данные, включая рекламный идентификатор вашего устройства, для предоставления рекламы и повышения стабильности приложения.',
    },
