      'posBlurBox': 'ぼかし位置を調整',
      'faqQ1': '動画をダウンロードするには？',
      'faqA1': '対応プラットフォームから動画リンクをコピーし、ホーム画面に貼り付けて「続行」をクリックします。',
      'faqQ2': 'マジック消しゴムの使い方は？',
      'faqA2': '画像や動画をアップロードし、透かしなどの不要な部分を囲い、「選択範囲を消去」をクリックします。',
      'faqQ3': '動画をカットするには？',
      'faqA3': 'メディアツールから「動画をカット」を選び、動画をアップロードして、スライダーまたはタイマーで残したい部分を選択します。',
      'faqQ4': 'ファイル形式を変換するには？',
      'faqA4': 'メディアツールから「形式変換」を選び、音声か動画を選択し、ファイルを選んでからMP3やMP4などの変換先形式を選択します。',
