      'faqQ5': 'ファイルはどこに保存されますか？',
      'faqA5': '動画と画像はフォトギャラリーに保存されます。音声ファイルは「ファイル」アプリの「Quick Save」フォルダにあります。',
      'faqQ6': '無料で使えますか？',
      'faqA6': 'はい、Quick Saveは完全に無料で使用できます！',
      'faqQ7': '対応しているプラットフォームは？',
      'faqA7': 'YouTube、Instagram、TikTok、Facebookに対応しています。',
      'faqQ9': 'どんなファイルでも圧縮できますか？',
      'faqA9': 'はい！ビデオ、画像（JPG、PNG、WebP）、オーディオ（MP3、WAVなど）を圧縮して、品質を維持しながら容量を節約できます。',
      'faqQ10': '動画から音を消すにはどうすればいいですか？',
      'faqA10': 'メディアツール > 音声を削除 に進みます。ギャラリーから動画を選択するか、リンクを貼り付けることができます。アプリが消音版の動画を生成します。',
      'faqQ11': 'YouTubeやTikTokのリンクからMP3を取得できますか？',
      'faqA11': 'はい、「MP3抽出」ツールを使用してください。リンクを貼り付けると、アプリは音声のみを取得し、高品質のMP3ファイルとして保存します。',
      'termsContent': '1. はじめに\nQuick Saveへようこそ。当社のアプリケーションにアクセスして使用することにより、お客様は以下の利用規約に従い、拘束されることに同意するものとします。同意されない場合は、本サービスを使用しないでください。\n\n2. サービスの説明\nQuick Saveは、サポートされているプラットフォームから動画や音声をダウンロードしたり、動画をカットしたり、メディア形式を変換したり、ファイルを圧縮したり（動画、画像、音声）、動画から音声を除去したり（ミュート）、動画ファイルから高品質のMP3を抽出したりするのに役立つユーティリティツールです。\n\n3. ユーザーの責任と著作権\nユーザーは、ダウンロードまたは編集したメディアに対して単独で責任を負います。著作権で保護された資料をダウンロードまたは処理する前に、コンテンツ所有者からの法的権利または許可があることを確認する必要があります。Quick Saveはコンテンツをホストしておらず、技術的な仲介者としてのみ機能します。\n\n4. 使用制限\n本アプリを違法な目的や著作権侵害を助長するために使用することはできません。適切な許可なしに処理済みのコンテンツを商業目的で使用することは固く禁じられています。\n\n5. 免責事項\nQuick Saveは「現状のまま」提供され、いかなる保証もありません。当社は、お客様によるアプリケーションの使用から生じる技術的な障害、データの損失、または法的問題について一切の責任を負いません。\n\n6. 規約の変更\n当社は、いつでもこれらの規約を変更する権利を留保します。アプリの継続的な使用は、更新された規約への同意を構成します。',
      'privacyContent': '1. データの収集\nお客様のプライバシーは当社の優先事項です。Quick Saveはアカウントを必要とせず、名前、メールアドレス、位置情報などの個人情報を収集、保存、または販売することはありません。\n\n2. デバイス上の処理\n動画のカット、形式変換、ファイル圧縮、音声削除、MP3抽出を含むほとんどの機能は、モバイルデバイス上で直接処理されます。メディアファイルはお客様個人のままであり、共有を選択しない限りデバイスから送信されることはありません。\n\n3. 一時的なサーバーの使用\nリンク経由で動画をダウンロードすると、当社のサーバーがメディアファイルを取得するためのリクエストを処理します。このデータは一時的に処理され、ダウンロードが完了した後はサーバーに永続的に保存されることはありません。\n\n4. 権限\nダウンロードしたメディアを保存し、編集（カット、変換、圧縮など）するファイルを選択できるようにする目的でのみ、フォトギャラリーと内部ストレージへのアクセスを要求します。\n\n5. サードパーティのリンク\n当社のアプリには、外部サイト（YouTube、Instagramなど）へのリンクが含まれている場合があります。当社は、これらのサードパーティプラットフォームのプライバシー慣行またはコンテンツについて責任を負いません。\n\n6. 同意\nQuick Saveを使用することにより、お客様は当社のプライバシーポリシーに同意するものとします。\n\n7. サードパーティのサービスと広告\nGoogle AdMobなどのサードパーティサービスを使用して、広告を表示し、アプリのパフォーマンスを監視します。これらのサービスは、広告を提供し、アプリの安定性を向上させるために、デバイスの広告IDを含む匿名データを収集する場合があります。',
    },
