      'faqA2': '이미지나 동영상을 업로드하고 워터마크나 원치 않는 요소 위에 상자를 그린 후 "선택 영역 지우기"를 클릭하세요.',
      'faqQ3': '동영상을 어떻게 자르나요?',
      'faqA3': '미디어 도구로 이동하여 동영상 자르기를 선택하고, 동영상을 업로드한 후 슬라이더나 타이머를 사용하여 보관할 부분을 선택하세요.',
      'faqQ4': '파일 형식을 어떻게 변환하나요?',
      'faqA4': '미디어 도구에서 "형식 변환"을 선택하고 오디오 또는 동영상 중에서 선택한 후 파일을 고르고 MP3나 MP4와 같은 대상 형식을 선택하세요.',
      'faqQ8': '동영상에 워터마크를 어떻게 추가하나요?',
      'faqA8': '미디어 도구 > 워터마크 추가로 이동하여 동영상을 선택하고 텍스트를 입력하거나 로고를 고른 후 위치를 선택하고 "동영상 처리"를 클릭하세요.',
      'faqQ5': '파일은 어디에 저장되나요?',
      'faqA5': '동영상과 이미지는 사진 갤러리에 저장됩니다. 오디오 파일은 "파일" 앱의 "Quick Save" 폴더에서 찾을 수 있습니다.',
      'faqQ6': '무료로 사용할 수 있나요?',
      'faqA6': '네, Quick Save는 완전히 무료로 이용 가능합니다!',
      'faqQ7': '지원되는 플랫폼은 무엇인가요?',
      'faqA7': 'YouTube, Instagram, TikTok, Facebook을 지원합니다.',
      'faqQ9': '어떤 파일이든 압축할 수 있나요?',
      'faqA9': '네! 품질을 유지하면서 공간을 절약하기 위해 비디오, 이미지(JPG, PNG, WebP) 및 오디오(MP3, WAV 등)를 압축할 수 있습니다.',
      'faqQ10': '동영상에서 소리를 어떻게 제거하나요?',
      'faqA10': '미디어 도구 > 오디오 제거로 이동하세요. 갤러리에서 동영상을 선택하거나 링크를 붙여넣을 수 있습니다. 앱이 소리가 제거된 동영상 버전을 생성해 드립니다.',
      'faqQ11': 'YouTube나 TikTok 링크에서 MP3를 얻을 수 있나요?',
      'faqA11': '네, "MP3 추출" 도구를 사용하면 됩니다. 링크를 붙여넣으면 앱이 오디오만 가져와 고품질 MP3 파일로 저장합니다.',
      'termsContent': '1. 서론\nQuick Save에 오신 것을 환영합니다. 본 애플리케이션에 접속하고 이용함으로써 귀하는 다음의 이용 약관을 준수하고 이에 구속되는 데 동의하게 됩니다. 동의하지 않는 경우 서비스를 이용하지 마십시오.\n\n2. 서비스 설명\nQuick Save는 사용자가 지원되는 플랫폼에서 동영상 및 오디오를 다운로드할 수 있도록 설계된 유틸리티 도구입니다. 또한 동영상 자르기, 형식 변환, 파일 압축(동영상, 이미지, 오디오), 동영상 오디오 제거(음소거), 모든 동영상 파일에서 고품질 MP3 추출 기능을 위한 전문 미디어 도구도 제공합니다.\n\n3. 사용자 책임 및 저작권\n사용자는 자신이 다운로드하거나 편집한 미디어에 대해 전적인 책임을 집니다. 저작권이 있는 자료를 다운로드하거나 처리하기 전에 콘텐츠 소유자로부터 법적 권리나 허가를 받았는지 확인해야 합니다. Quick Save는 어떠한 콘텐츠도 호스팅하지 않으며 기술적 중개자 역할만 합니다.\n\n4. 사용 제한\n불법적인 목적이나 저작권 침해를 조장하기 위해 본 앱을 사용할 수 없습니다. 적절한 승인 없이 처리된 콘텐츠를 상업적으로 이용하는 것은 엄격히 금지됩니다.\n\n5. 책임의 한계\nQuick Save는 어떠한 보증 없이 "있는 그대로" 제공됩니다. 당사는 귀하의 애플리케이션 사용으로 인해 발생하는 기술적 장애, 데이터 손실 또는 법적 문제에 대해 책임을 지지 않습니다.\n\n6. 약관 변경\n당사는 언제든지 본 약관을 수정할 권리가 있습니다. 앱을 계속 사용하면 업데이트된 약관에 동의하는 것으로 간주됩니다.',
      'privacyContent': '1. 데이터 수집\n귀하의 개인정보 보호는 당사의 최우선 과제입니다. Quick Save는 계정을 필요로 하지 않으며, 이름, 이메일 또는 위치와 같은 개인 정보를 수집, 저장 또는 판매하지 않습니다.\n\n2. 기기 내 처리\n동영상 자르기, 형식 변환, 파일 압축, 오디오 제거 및 MP3 추출을 포함한 대부분의 기능은 모바일 기기에서 직접 처리됩니다. 귀하의 미디어 파일은 개인적으로 유지되며 공유를 선택하지 않는 한 기기를 떠나지 않습니다.\n\n3. 임시 서버 사용\n링크를 통해 동영상을 다운로드하면 당사 서버가 미디어 파일을 가져오기 위한 요청을 처리합니다. 이 데이터는 일시적으로 처리되며 다운로드가 완료된 후에는 서버에 영구적으로 저장되지 않습니다.\n\n4. 권한\n다운로드한 미디어를 저장하고 편집(자르기, 변환, 압축 등)할 파일을 선택할 수 있도록 하기 위한 목적으로만 사진 갤러리 및 내부 저장소에 대한 접근 권한을 요청합니다.\n\n5. 제3자 링크\n당사 앱에는 외부 사이트(YouTube, Instagram 등)에 대한 링크가 포함될 수 있습니다. 당사는 이러한 제3자 플랫폼의 개인정보 보호 관행이나 콘텐츠에 대해 책임을 지지 않습니다.\n\n6. 동의\nQuick Save를 이용함으로써 귀하는 당사의 개인정보 처리방침에 동의하게 됩니다.\n\n7. 타사 서비스 및 광고\nGoogle AdMob과 같은 타사 서비스를 사용하여 광고를 표시하고 앱 성능을 모니터링합니다. 이러한 서비스는 광고를 제공하고 앱 안정성을 개선하기 위해 기기의 광고 ID를 포함한 익명 데이터를 수집할 수 있습니다.',
    },
