      'openGallery': 'গ্যালারি খুলুন',
      'posBlurBox': 'ব্লার বক্সটি বসান',
      'faqQ1': 'কীভাবে একটি ভিডিও ডাউনলোড করবেন?',
      'faqA1': 'যেকোনো সমর্থিত প্ল্যাটফর্ম থেকে ভিডিও লিঙ্কটি কপি করুন, হোম স্ক্রিনে পেস্ট করুন এবং চালিয়ে যান-এ ক্লিক করুন।',
      'faqQ2': 'ম্যাজিক ইরেজার কীভাবে ব্যবহার করবেন?',
      'faqA2': 'একটি ছবি বা ভিডিও আপলোড করুন, জলছাপ বা অবাঞ্ছিত উপাদানের উপর একটি বক্স আঁকুন এবং "নির্বাচিত এলাকা মুছুন"-এ ক্লিক করুন।',
      'faqQ3': 'কীভাবে একটি ভিডিও ট্রিম করবেন?',
      'faqA3': 'মিডিয়া টুলস-এ যান, ভিডিও ট্রিম নির্বাচন করুন, আপনার ভিডিও আপলোড করুন এবং যে অংশটি রাখতে চান তা নির্বাচন করতে স্লাইডার বা কাস্টম টাইমার ব্যবহার করুন।',
      'faqQ4': 'ফাইলের ফরম্যাট কীভাবে পরিবর্তন করবেন?',
      'faqA4': 'মিডিয়া টুলস থেকে "ফরম্যাট পরিবর্তন" নির্বাচন করুন, অডিও বা ভিডিও-র মধ্যে বেছে নিন, আপনার ফাইলটি নিন এবং টার্গেট ফরম্যাট যেমন MP3 বা MP4 বেছে নিন।',
      'faqQ8': 'আমার ভিডিওতে জলছাপ কীভাবে যোগ করব?',
      'faqA8': 'মিডিয়া টুলস > জলছাপ যোগ করুন-এ যান, আপনার ভিডিওটি নির্বাচন করুন, টেক্সট দিন বা একটি লোগো বেছে নিন, অবস্থান ঠিক করুন এবং "ভিডিও প্রসেস করুন"-এ ক্লিক করুন।',
      'faqQ5': 'আমার ফাইলগুলো কোথায় সেভ হয়?',
      'faqA5': 'ভিডিও এবং ছবিগুলো আপনার ফটো গ্যালারিতে সেভ হয়। অডিও ফাইলগুলো "ফাইলস" অ্যাপের "Quick Save" ফোল্ডারে পাওয়া যাবে।',
      'faqQ6': 'এটি কি ব্যবহার করা ফ্রি?',
      'faqA6': 'হ্যাঁ, Quick Save ব্যবহার করা সম্পূর্ণ ফ্রি!',
      'faqQ7': 'সমর্থিত প্ল্যাটফর্মগুলো কী কী?',
      'faqA7': 'আমরা YouTube, Instagram, TikTok এবং Facebook সমর্থন করি।',
      'faqQ9': 'আমি কি যেকোনো ফাইল কম্প্রেস করতে পারি?',
      'faqA9': 'হ্যাঁ! গুণমান বজায় রেখে জায়গা বাঁচাতে আপনি ভিডিও, ছবি (JPG, PNG, WebP) এবং অডিও (MP3, WAV ইত্যাদি) কম্প্রেস করতে পারেন।',
      'faqQ10': 'একটি ভিডিও থেকে শব্দ কীভাবে সরিয়ে ফেলব?',
      'faqA10': 'মিডিয়া টুলস > অডিও সরান-এ যান। আপনি আপনার গ্যালারি থেকে একটি ভিডিও নিতে পারেন অথবা একটি লিঙ্ক পেস্ট করতে পারেন। অ্যাপটি আপনার জন্য ভিডিওর একটি মিউট সংস্করণ তৈরি করবে।',
      'faqQ11': 'আমি কি ইউটিউব বা টিকটক লিঙ্ক থেকে MP3 পেতে পারি?',
      'faqA11': 'হ্যাঁ, শুধু "MP3 বের করুন" টুলটি ব্যবহার করুন। লিঙ্কটি পেস্ট করুন, এবং অ্যাপটি শুধুমাত্র অডিওটি সংগ্রহ করবে এবং সেটিকে উচ্চমানের MP3 ফাইল হিসেবে সেভ করবে।',
      'termsContent': '১. ভূমিকা\nQuick Save-এ আপনাকে স্বাগতম। আমাদের অ্যাপ্লিকেশনটি অ্যাক্সেস এবং ব্যবহার করে, আপনি নিম্নলিখিত নিয়ম ও শর্তাবলী মেনে চলতে এবং সেগুলির দ্বারা আবদ্ধ হতে সম্মত হন। আপনি যদি সম্মত না হন, তবে দয়া করে পরিষেবাটি ব্যবহার করবেন না।\n\n২. পরিষেবার বিবরণ\nQuick Save হল একটি ইউটিলিটি টুল যা ব্যবহারকারীদের সমর্থિત প্ল্যাটফর্ম থেকে ভিডিও এবং অডিও ডাউনলোড করতে, ভিডিও ট্রিম করতে, মিডিয়া ফরম্যাট পরিবর্তন করতে এবং ম্যাজিক ইরেজার ব্যবহার করে অবাঞ্ছিত উপাদানগুলি সরিয়ে ফেলতে সাহায্য করার জন্য ডিজাইন করা হয়েছে।\n\n৩. ব্যবহারকারীর দায়িত্ব এবং কপিরাইট\nব্যবহারকারীরা তাদের ডাউনলোড করা বা এডিট করা মিডিয়ার জন্য সম্পূর্ণ দায়বদ্ধ। কপিরাইটযুক্ত উপাদান ডাউনলোড করার আগে আপনাকে অবশ্যই নিশ্চিত করতে হবে যে আপনার কাছে কন্টেন্ট মালিকের আইনি অধিকার বা অনুমতি রয়েছে। Quick Save কোনো কন্টেন্ট হোস্ট করে না এবং শুধুমাত্র একটি প্রযুক্তিগত মধ্যস্থতাকারী হিসেবে কাজ করে।\n\n৪. ব্যবহারের বিধিনিষেধ\nআপনি কোনো অবৈধ উদ্দেশ্যে বা কপিরাইট লঙ্ঘন সহজতর করার জন্য এই অ্যাপটি ব্যবহার করতে পারবেন না। যথাযথ অনুমতি ছাড়া ডাউনলোড করা কন্টেন্টের বাণিজ্যিক ব্যবহার কঠোরভাবে নিষিদ্ধ।\n\n৫. দায়বদ্ধতার সীমাবদ্ধতা\nQuick Save কোনো ওয়ারেন্টি ছাড়াই \"যেমন আছে\" ভিত্তিতে প্রদান করা হয়। অ্যাপ্লিকেশনটির ব্যবহারের ফলে কোনো প্রযুক্তিগত ত্রুটি, ডেটা হারানো বা আইনি সমস্যার জন্য আমরা দায়ী নই।\n\n৬. শর্তাবলীর পরিবর্তন\nআমরা যেকোনো সময় এই শর্তাবলী সংশোধন করার अधिकार সংরক্ষণ করি। অ্যাপটির ক্রমাগত ব্যবহার আপডেট করা শর্তাবলীর স্বীকৃতি হিসেবে গণ্য হবে।',
      'privacyContent': '১. তথ্য সংগ্রহ\nআপনার গোপনীয়তা আমাদের অগ্রাধিকার। Quick Save-এর জন্য কোনো অ্যাকাউন্টের প্রয়োজন নেই এবং আমরা আপনার নাম, ইমেল বা অবস্থানের মতো কোনো ব্যক্তিগত তথ্য সংগ্রহ, সংরক্ষণ বা বিক্রি করি না।\n\n২. ডিভাইসে প্রসেসিং\nভি디오 ট্রিমিంగ్, ফরম্যাট রূপান্তর এবং স্থানীয় ইতিহাস ব্যবস্থাপনা সহ বেশিরভাগ বৈশিষ্ট্য সরাসরি আপনার মোবাইল ডিভাইসে প্রসেস করা হয়। আপনার মিডিয়া ফাইলগুলি আপনার কাছে ব্যক্তিগত থাকে।\n\n৩. সাময়িক সার্ভার ব্যবহার\nআপনি যখন লিঙ্কের মাধ্যমে একটি ভিডিও ডাউনলোড করেন, আমাদের সার্ভার মিডিয়া ফাইলটি আনার অনুরোধ প্রসেস করে। এই ডেটা সাময়িকভাবে প্রসেস করা হয় এবং ডাউনলোড সম্পন্ন হওয়ার পর আমাদের সার্ভারে স্থায়ীভাবে সংরক্ষণ করা হয় না।\n\n৪. অনুমতি\nআমরা ডাউনলোড করা মিডিয়া সেভ করতে এবং আপনাকে এডিটিং (ট্রিമിং, কনভার্টিং ইত্যাদি) এর জন্য ফাইল নির্বাচন করতে দেওয়ার উদ্দেশ্যেই আপনার ফটো গ্যালারি এবং ইন্টারনাল স্টোরেজ অ্যাক্সেস করার অনুরোধ করি।\n\n৫. তৃতীয় পক্ষের লিঙ্ক\nআমাদের অ্যাপে বাইরের সাইটগুলোর (যেমন YouTube, Instagram) লিঙ্ক থাকতে পারে। আমরা এই তৃতীয় পক্ষের প্ল্যাটফর্মগুলির গোপনীয়তা নীতি বা কন্টেন্টের জন্য দায়ী নই।\n\n৬. সম্মতি\nQuick Save ব্যবহার করার মাধ্যমে, আপনি আমাদের গোপনীয়তা নীতিতে সম্মতি দিচ্ছেন।\n\n7. তৃতীয় পক্ষের পরিষেবা এবং বিজ্ঞাপন\nআমরা বিজ্ঞাপন প্রদর্শন করতে এবং অ্যাপের পারফরম্যান্স নিরীক্ষণ করতে Google AdMob-এর মতো তৃতীয় পক্ষের পরিষেবা ব্যবহার করি। বিজ্ঞাপন প্রদান করতে এবং অ্যাপের স্থায়িত্ব উন্নত করতে এই পরিষেবাগুলি আপনার ডিভাইসের বিজ্ঞাপন আইডি সহ বেনামী ডেটা সংগ্রহ করতে পারে।',
    },
