      'faqQ1': 'వీడియోను డౌన్‌లోడ్ చేయడం ఎలా?',
      'faqA1': 'మద్దతు ఉన్న ప్లాట్‌ఫారమ్ నుండి వీడియో లింక్‌ను కాపీ చేసి, హోమ్ స్క్రీన్‌లో పేస్ట్ చేసి, కొనసాగించు క్లిక్ చేయండి.',
      'faqQ2': 'మ్యాజిక్ ఎరేజర్‌ను ఎలా ఉపయోగించాలి?',
      'faqA2': 'చిత్రం లేదా వీడియోను అప్‌లోడ్ చేయండి, వాటర్ మార్క్ లేదా అనవసరమైన ఎలిమెంట్‌పై బాక్స్‌ను గీయండి మరియు "ఎంచుకున్న ప్రాంతాన్ని తొలగించు" క్లిక్ చేయండి.',
      'faqQ3': 'వీడియోను ఎలా ట్రిమ్ చేయాలి?',
      'faqA3': 'మీడియా టూల్స్‌కు వెళ్లి, వీడియో ట్రిమ్ ఎంచుకోండి, మీ వీడియోను అప్‌లోడ్ చేయండి మరియు మీరు ఉంచుకోవాలనుకునే భాగాన్ని ఎంచుకోవడానికి స్లైడర్ లేదా కస్టమ్ టైమర్‌ని ఉపయోగించండి.',
      'faqQ4': 'ఫైల్ ఫార్మాట్‌లను ఎలా మార్చాలి?',
      'faqA4': 'మీడియా టూల్స్ నుండి "ఫార్మాట్ మార్చండి" ఎంచుకోండి, ఆడియో లేదా వీడియో మధ్య ఎంచుకోండి, మీ ఫైల్‌ను ఎంచుకోండి మరియు MP3 లేదా MP4 వంటి టార్గెట్ ఫార్మాట్‌ను ఎంచుకోండి.',
      'faqQ8': 'నా వీడియోకు వాటర్ మార్క్‌ను ఎలా జోడించాలి?',
      'faqA8': 'మీడియా టూల్స్ > వాటర్ మార్క్ జోడించండికి వెళ్లి, మీ వీడియోను ఎంచుకోండి, వచనాన్ని నమోదు చేయండి లేదా లోగోను ఎంచుకోండి, స్థానాన్ని ఎంచుకుని, "వీడియోను ప్రాసెస్ చేయి" క్లిక్ చేయండి.',
      'faqQ5': 'నా ఫైల్‌లు ఎక్కడ సేవ్ చేయబడతాయి?',
      'faqA5': 'వీడియోలు మరియు చిత్రాలు మీ ఫోటో గ్యాలరీలో సేవ్ చేయబడతాయి. ఆడియో ఫైల్‌లు "ఫైల్స్" యాప్‌లో "Quick Save" ఫోల్డర్‌లో ఉంటాయి.',
      'faqQ6': 'ఇది ఉచితమేనా?',
      'faqA6': 'అవును, Quick Save ఉపయోగించడం పూర్తిగా ఉచితం!',
      'faqQ7': 'మద్దతు ఉన్న ప్లాట్‌ఫారమ్‌లు?',
      'faqA7': 'మేము YouTube, Instagram, TikTok మరియు Facebookకి మద్దతు ఇస్తున్నాము.',
      'faqQ9': 'నేను ఏదైనా ఫైల్‌ను కంప్రెస్ చేయవచ్చా?',
      'faqA9': 'అవును! నాణ్యతను కాపాడుకుంటూ స్థలాన్ని ఆదా చేయడానికి మీరు వీడియోలు, చిత్రాలు (JPG, PNG, WebP) మరియు ఆడియో (MP3, WAV మొదలైనవి) కంప్రెస్ చేయవచ్చు.',
      'faqQ10': 'వీడియో నుండి ధ్వనిని ఎలా తొలగించాలి?',
      'faqA10': 'మీడియా టూల్స్ > ఆడియోను తొలగించుకి వెళ్లండి. మీరు మీ గ్యాలరీ నుండి వీడియోను ఎంచుకోవచ్చు లేదా లింక్‌ని పేస్ట్ చేయవచ్చు. యాప్ మీ కోసం వీడియో యొక్క మ్యూట్ వెర్షన్‌ను రూపొందిస్తుంది.',
      'faqQ11': 'నేను YouTube లేదా TikTok లింక్ నుండి MP3ని పొందవచ్చా?',
      'faqA11': 'అవును, కేవలం "MP3 సంగ్రహించు" సాధనాన్ని ఉపయోగించండి. లింక్‌ను పేస్ట్ చేయండి, యాప్ ఆడియోను మాత్రమే సేకరించి అధిక నాణ్యత గల MP3 ఫైల్‌గా సేవ్ చేస్తుంది.',
      'termsContent': '1. పరిచయం\nQuick Saveకి స్వాగతం. మా అప్లికేషన్‌ను యాక్సెస్ చేయడం మరియు ఉపయోగించడం ద్వారా, మీరు ఈ క్రింది నిబంధనలు మరియు షరతులకు కట్టుబడి ఉండటానికి అంగీకరిస్తున్నారు. మీరు అంగీకరించకపోతే, దయచేసి సేవను ఉపయోగించవద్దు.\n\n2. సేవ యొక్క వివరణ\nQuick Save అనేది మద్దతు ఉన్న ప్లాట్‌ఫారమ్‌ల నుండి వీడియో మరియు ఆడియోను డౌన్‌లోడ్ చేయడానికి, వీడియోలను ట్రిమ్ చేయడానికి, మీడియా ఫార్మాట్‌లను మార్చడానికి మరియు మ్యాజిక్ ఎరేజర్‌ను ఉపయోగించి అనవసరమైన అంశాలను తొలగించడానికి వినియోగదారులకు సహాయపడే ఒక యుటిలిటీ సాధనం.\n\n3. వినియోగదారు బాధ్యత & కాపీరైట్\nవినియోగదారులు డౌన్‌లోడ్ చేసే లేదా ఎడిట్ చేసే మీడియాకు వారే పూర్తి బాధ్యత వహిస్తారు. కాపీరైట్ చేయబడిన మెటీరియల్‌ని డౌన్‌లోడ్ చేయడానికి ముందు కంటెంట్ యజమాని నుండి మీకు చట్టపరమైన హక్కు లేదా అనుమతి ఉందని మీరు నిర్ధారించుకోవాలి. Quick Save ఎటువంటి కంటెంట్‌ను హోస్ట్ చేయదు మరియు కేవలం సాంకేతిక మధ్యవర్తిగా మాత్రమే పనిచేస్తుంది.\n\n4. వినియోగ పరిమితులు\nమీరు ఈ యాప్‌ను ఎటువంటి చట్టవిరుద్ధమైన ప్రయోజనాల కోసం లేదా కాపీరైట్ ఉల్లంఘనకు సహకరించడానికి ఉపయోగించకూడదు. సరైన అనుమతి లేకుండా డౌన్‌లోడ్ చేసిన కంటెంట్‌ను వాణిజ్యపరంగా ఉపయోగించడం ఖచ్చితంగా నిషేధించబడింది.\n\n5. బాధ్యత పరిమితి\nQuick Save ఎటువంటి వారంటీలు లేకుండా \"ఉన్నది ఉన్నట్లుగా\" అందించబడుతుంది. అప్లికేషన్ యొక్క మీ వినియోగం నుండి ఉత్పన్నమయ్యే ఎటువంటి సాంకేతిక వైఫల్యాలు, డేటా నష్టం లేదా చట్టపరమైన సమస్యలకు మేము బాధ్యత వహించము.\n\n6. నిబంధనలలో మార్పులు\nఈ నిబంధనలను ఎప్పుడైనా సవరించే హక్కు మాకు ఉంది. యాప్ యొక్క నిరంతర వినియోగం నవీకరించబడిన నిబంధనలను అంగీకరించినట్లుగా పరిగణించబడుతుంది.',
      'privacyContent': '1. డేటా సేకరణ\nమీ గోప్యత మా ప్రాధాన్యత. Quick Saveకి ఎటువంటి ఖాతా అవసరం లేదు మరియు మేము మీ పేరు, ఇమెయిల్ లేదా స్థానం వంటి వ్యక్తిగత సమాచారాన్ని సేకరించము, నిల్వ చేయము లేదా విక్రయించము.\n\n2. పరికరంలో ప్రాసెసింగ్\nవీడియో ట్రిమ్మింగ్, ఫార్మాట్ మార్పిడి మరియు స్థానిక చరిత్ర నిర్వహణతో సహా చాలా ఫీచర్‌లు నేరుగా మీ మొబైల్ పరికరంలో ప్రాసెస్ చేయబడతాయి. మీ మీడియా ఫైల్‌లు మీకు గోప్యంగా ఉంటాయి.\n\n3. తాత్కాలిక సర్వర్ వినియోగం\nమీరు లింక్ ద్వారా వీడియోను డౌన్‌లోడ్ చేసినప్పుడు, మీడియా ఫైల్‌ను పొందడానికి మా సర్వర్ అభ్యర్థనను ప్రాసెస్ చేస్తుంది. ఈ డేటా తాత్కాలికంగా ప్రాసెస్ చేయబడుతుంది మరియు డౌన్‌లోడ్ పూర్తయిన తర్వాత మా సర్వర్‌లలో శాశ్వతంగా నిల్వ చేయబడదు.\n\n4. అనుమతులు\nడౌన్‌లోడ్ చేసిన మీడియాను సేవ్ చేయడానికి మరియు ఎడిటింగ్ (ట్రిమ్మింగ్, కన్వర్టింగ్ మొదలైనవి) కోసం ఫైల్‌లను ఎంచుకోవడానికి మిమ్మల్ని అనుమతించే ఉద్దేశ్యంతో మాత్రమే మేము మీ ఫోటో గ్యాలరీ మరియు అంతర్గత నిల్వకు ప్రాప్యతను అభ్యర్థిస్తాము.\n\n5. థర్డ్-పార్టీ లింక్‌లు\nమా యాప్‌లో బాహ్య సైట్‌ల (YouTube, Instagram వంటివి) లింక్‌లు ఉండవచ్చు. ఈ థర్డ్-పార్టీ ప్లాట్‌ఫారమ్‌ల గోప్యతా పద్ధతులు లేదా కంటెంట్‌కు మేము బాధ్యత వహించము.\n\n6. సమ్మతి\nQuick Saveని ఉపయోగించడం ద్వారా, మీరు మా గోప్యతా విధానానికి అంగరీకరిస్తున్నారు.\n\n7. థర్డ్-పార్టీ సేవలు మరియు ప్రకటనలు\nప్రకటనలను ప్రదర్శించడానికి మరియు యాప్ పనితీరును పర్యవేక్షించడానికి మేము Google AdMob వంటి థర్డ్-పార్టీ సేవలను ఉపయోగిస్తాము. ప్రకటనలను అందించడానికి మరియు యాప్ స్థిరత్వాన్ని మెరుగుపరచడానికి ఈ సేవలు మీ పరికరం యొక్క అడ్వర్టైజింగ్ IDతో సహా అనామక డేటాను సేకరించవచ్చు.',
    },
