      'posBlurBox': 'ब्लर बॉक्स ठेवा',
      'faqQ1': 'व्हिडिओ कसा डाउनलोड करायचा?',
      'faqA1': 'कोणत्याही समर्थित प्लॅटफॉर्मवरून व्हिडिओ लिंक कॉपी करा, होम स्क्रीनवर पेस्ट करा आणि पुढे जा क्लिक करा.',
      'faqQ2': 'मॅजिक इरेजर कसे वापरायचे?',
      'faqA2': 'फोटो किंवा व्हिडिओ अपलोड करा, वॉटरमार्क किंवा नको असलेल्या घटकावर बॉक्स काढा आणि "निवडलेला भाग पुसा" वर क्लिक करा.',
      'faqQ3': 'व्हिडिओ ट्रिम कसा करायचा?',
      'faqA3': 'मीडिया टूल्सवर जा, व्हिडिओ ट्रिम निवडा, तुमचा व्हिडिओ अपलोड करा आणि तुम्हाला हवा असलेला भाग निवडण्यासाठी स्लायडर किंवा कस्टम टाइमर वापरा.',
      'faqQ4': 'फाईल फॉरमॅट कसे बदलायचे?',
      'faqA4': 'मीडिया टूल्समधून "फॉर्मेट बदला" निवडा, ऑडिओ किंवा व्हिडिओपैकी एक निवडा, तुमची फाईल निवडा आणि MP3 किंवा MP4 सारखा टार्गेट फॉर्मेट निवडा.',
      'faqQ8': 'माझ्या व्हिडिओमध्ये वॉटरमार्क कसा जोडायचा?',
      'faqA8': 'मीडिया टूल्स > वॉटरमार्क जोडा वर जा, तुमचा व्हिडिओ निवडा, मजकूर लिहा किंवा लोगो निवडा, स्थिती निवडा आणि "व्हिडिओवर प्रक्रिया करा" वर क्लिक करा.',
      'faqQ5': 'माझ्या फाईल्स कुठे सेव्ह होतात?',
      'faqA5': 'व्हिडिओ आणि फोटो तुमच्या फोटो गॅलरीमध्ये सेव्ह होतात. ऑडिओ फाईल्स "Files" ॲपमध्ये "Quick Save" फोल्डरमध्ये मिळतील.',
      'faqQ6': 'हे वापरणे विनामूल्य आहे का?',
      'faqA6': 'हो, Quick Save वापरणे पूर्णपणे विनामूल्य आहे!',
      'faqQ7': 'समर्थित प्लॅटफॉर्म कोणते आहेत?',
      'faqA7': 'आम्ही YouTube, Instagram, TikTok आणि Facebook ला सपोर्ट करतो.',
      'termsContent': '1. परिचय\nQuick Save मध्ये आपले स्वागत आहे। आमचे ॲप्लिकेशन वापरून तुम्ही खालील अटी व शर्तींचे पालन करण्यास आणि त्यास बांधील राहण्यास संमती देता। आपण सहमत नसल्यास, कृपया सेवा वापरू नका।\n\n2. सेवेचे वर्णन\nQuick Save हे एक युटिलिटी साधन आहे जे वापरकर्त्यांना समर्थित प्लॅटफॉर्मवरून व्हिडिओ आणि ऑडिओ डाउनलोड करण्यासाठी, व्हिडिओ ट्रिम करण्यासाठी, मडिया फॉरमॅट बदलण्यासाठी आणि मॅजिक इरेजर वापरून नको असलेले घटक काढून टाकण्यासाठी मदत करते।\n\n3. वापरकर्त्याची जबाबदारी आणि कॉपीराइट\nवापरकर्ते त्यांनी डाउनलोड केलेल्या किंवा संपादित केलेल्या मीडियासाठी स्वतः जबाबदार आहेत। कॉपीराइट केलेली सामग्री डाउनलोड करण्यापूर्वी आपल्याकडे सामग्री मालकाचा कायदेशीर अधिकार किंवा परवानगी असल्याची खात्री करणे आवश्यक आहे। Quick Save कोणतीही सामग्री होस्ट करत नाही आणि केवळ तांत्रिक मध्यस्थ म्हणून कार्य करते।\n\n4. वापर निर्बंध\nतुम्ही हे ॲप कोणत्याही बेकायदेशीर हेतूसाठी किंवा कॉपीराइट उल्लंघनास मदत करण्यासाठी वापरू शकत नाही। योग्य परवानगीशिवाय डाउनलोड केलेल्या सामग्रीचा व्यावसायिक वापर करण्यास सक्त मनाई आहे।\n\n5. दायित्वाची मर्यादा\nQuick Save कोणत्याही हमीशिवाय \"जसे आहे तसे\" प्रदान केले जाते। अनुप्रयोगाच्या वापरामुळे उद्भवणाऱ्या कोणत्याही तांत्रिक बिघाड, डेटा गमावणे किंवा कायदेशीर समस्यांसाठी आम्ही जबाबदार नाही।\n\n6. अटींमधील बदल\nआम्ही या अटी कधीही सुधारण्याचा अधिकार राखून ठेवतो। ॲपचा सतत वापर म्हणजे सुधारित अटींचा स्वीकार मानला जाईल।',
      'privacyContent': '1. डेटा संकलन\nतुमची गोपनीयता आमची प्राथमिकता आहे। Quick Save ला खाते आवश्यक नाही आणि आम्ही तुमचे नाव, ईमेल किंवा स्थान यासारखी कोणतीही वैयक्तिक माहिती गोळा, संग्रहित किंवा विक्री करत नाही।\n\n2. ऑन-डिव्हाइस प्रोसेसिंग\nव्हिडिओ ट्रिमिंग, फॉरमॅट रूपांतरण आणि स्थानिक इतिहास व्यवस्थापन यासह बहुतेक वैशिष्ट्ये थेट तुमच्या मोबाइल डिव्हाइसवर प्रक्रिया केली जातात। तुमच्या मीडिया फाईल्स तुमच्यासाठी खाजगी राहतात।\n\n3. तात्पुरता सर्व्हर वापर\nजेव्हा तुम्ही लिंकद्वारे व्हिडिओ डाउनलोड करता, तेव्हा आमचा सर्व्हर मडिया फाईल मिळवण्यासाठी विनंतीवर प्रक्रिया करतो। हा डेटा तात्पुरता प्रक्रिया केला जातो आणि डाउनलोड पूर्ण झाल्यानंतर आमच्या सर्व्हरवर कायमस्वरूपी संग्रहित केला जात नाही।\n\n4. परवानग्या\nआम्ही डाउनलोड केलेला मीडिया सेव्ह करण्यासाठी आणि तुम्हाला संपादनासाठी (ट्रिमिंग, रूपांतरण इ.) फाईल्स निवडण्याची परवानगी देण्यासाठी केवळ तुमच्या फोटो गॅलरी आणि अंतर्गत स्टोरेजमध्ये प्रवेश करण्याची विनंती करतो।\n\n5. तृतीय-पक्ष लिंक\nआमच्या ॲपमध्ये बाह्य साइट्सच्या (उदा. YouTube, Instagram) लिंक असू शकतात। आम्ही या तृतीय-पक्ष प्लॅटफॉर्मच्या गोपनीयता पद्धती किंवा सामग्रीसाठी जबाबदार नाही।\n\n6. संमती\nQuick Save वापरून, तुम्ही आमच्या गोपनीयता धोरणास संमती देता।\n\n7. तृतीय-पक्ष सेवा आणि जाहिराती\nआम्ही जाहिराती प्रदर्शित करण्यासाठी आणि ॲप कार्यप्रदर्शनाचे निरीक्षण करण्यासाठी Google AdMob सारख्या तृतीय-पक्ष सेवा वापरतो. जाहिराती प्रदान करण्यासाठी आणि ॲप स्थिरता सुधारण्यासाठी या सेवा तुमच्या डिव्हाइसच्या जाहिरात आयडीसह निनावी डेटा गोळा करू शकतात.',
    },
