      'posBlurBox': 'மங்கலாக்கும் பெட்டியை வைக்கவும்',
      'faqQ1': 'வீடியோவை பதிவிறக்குவது எப்படி?',
      'faqA1': 'ஆதரிக்கப்படும் எந்த தளத்திலிருந்தும் வீடியோ இணைப்பை நகலெடுத்து, முகப்புத் திரையில் ஒட்டி, தொடரவும் என்பதைக் கிளிக் செய்யவும்.',
      'faqQ2': 'மேஜிக் அழிப்பானை எப்படி பயன்படுத்துவது?',
      'faqA2': 'ஒரு படம் அல்லது வீடியோவைப் பதிவேற்றவும், வாட்டர்மார்க் அல்லது தேவையற்ற உறுப்பு மீது ஒரு பெட்டியை வரையவும், பின்னர் "தேர்ந்தெடுக்கப்பட்ட பகுதியை அழி" என்பதைக் கிளிக் செய்யவும்.',
      'faqQ3': 'வீடியோவை வெட்டுவது எப்படி?',
      'faqA3': 'மீடியா கருவிகளுக்குச் சென்று, வீடியோவை வெட்டு என்பதைத் தேர்ந்தெடுத்து, உங்கள் வீடியோவைப் பதிவேற்றவும், ஸ்லைடர் அல்லது டைமரைப் பயன்படுத்தி நீங்கள் வைக்க விரும்பும் பகுதியைத் தேர்ந்தெடுக்கவும்.',
      'faqQ4': 'கோப்பு வடிவங்களை எப்படி மாற்றுவது?',
      'faqA4': 'மீடியா கருவிகளில் இருந்து "வடிவத்தை மாற்றவும்" என்பதைத் தேர்ந்தெடுத்து, ஆடியோ அல்லது வீடியோவில் ஒன்றைத் தேர்ந்தெடுக்கவும், உங்கள் கோப்பைத் தேர்ந்தெடுத்து, MP3 அல்லது MP4 போன்ற இலக்கு வடிவத்தைத் தேர்ந்தெடுக்கவும்.',
      'faqQ8': 'எனது வீடியோவில் வாட்டர்மார்க் சேர்ப்பது எப்படி?',
      'faqA8': 'மீடியா கருவிகள் > வாட்டர்மார்க் சேர்க்கவும் என்பதற்குச் சென்று, உங்கள் வீடியோவைத் தேர்ந்தெடுத்து, உரையை உள்ளிடவும் அல்லது லோகோவைத் தேர்ந்தெடுக்கவும், நிலையைத் தேர்ந்தெடுத்து, "வீடியோவைச் செயலாக்கு" என்பதைக் கிளிக் செய்யவும்.',
      'faqQ5': 'எனது கோப்புகள் எங்கே சேமிக்கப்படுகின்றன?',
      'faqA5': 'வீடியோக்களும் படங்களும் உங்கள் புகைப்படக் கேலரியில் சேமிக்கப்படும். ஆடியோ கோப்புகளை "கோப்புகள்" பயன்பாட்டில் "Quick Save" கோப்புறையில் காணலாம்.',
      'faqQ6': 'இதைப் பயன்படுத்துவது இலவசமா?',
      'faqA6': 'ஆம், Quick Save பயன்படுத்துவது முற்றிலும் இலவசம்!',
      'faqQ7': 'ஆதரிக்கப்படும் தளங்கள் எவை?',
      'faqA7': 'நாங்கள் YouTube, Instagram, TikTok மற்றும் Facebook ஐ ஆதரிக்கிறோம்.',
      'termsContent': '1. அறிமுகம்\nQuick Save-க்கு உங்களை வரவேற்கிறோம்। எங்கள் செயலியை அணுகுவதன் மூலமும் பயன்படுத்துவதன் மூலமும், பின்வரும் விதிமுறைகள் மற்றும் நிபந்தனைகளுக்கு இணங்கவும் அவற்றுக்கு கட்டுப்படவும் ஒப்புக்கொள்கிறீர்கள்। நீங்கள் உடன்படவில்லை என்றால், தயவுசெய்து சேவையைப் பயன்படுத்த வேண்டாம்।\n\n2. சேவையின் விளக்கம்\nQuick Save என்பது ஆதரிக்கப்படும் தளங்களில் இருந்து வீடியோ மற்றும் ஆடியோவைப் பதிவிறக்கவும், வீடியோக்களை வெட்டவும், மீடியா வடிவங்களை மாற்றவும் மற்றும் மேஜிக் அழிப்பானைப் பயன்படுத்தி தேவையற்ற கூறுகளை அகற்றவும் பயனர்களுக்கு உதவும் வகையில் வடிவமைக்கப்பட்ட ஒரு கருவியாகும்।\n\n3. பயனர் பொறுப்பு மற்றும் பதிப்புரிமை\nபயனர்கள் பதிவிறக்கம் செய்யும் அல்லது எடிட் செய்யும் மீடியாவிற்கு அவர்களே முழுப் பொறுப்பாவார்கள்। பதிப்புரிமை பெற்ற உள்ளடக்கத்தைப் பதிவிறக்குவதற்கு முன், உள்ளடக்க உரிமையாளரிடமிருந்து உங்களுக்கு சட்டப்பூர்வ உரிமை அல்லது அனுமதி இருப்பதை உறுதி செய்ய வேண்டும்। Quick Save எந்த உள்ளடக்கத்தையும் ஹோஸ்ட் செய்யாது மற்றும் ஒரு தொழில்நுட்ப இடைத்தரகராக மட்டுமே செயல்படுகிறது।\n\n4. பயன்பாட்டுக் கட்டுப்பாடுகள்\nஇந்தச் செயலியை சட்டவிரோதமான நோக்கங்களுக்காக அல்லது பதிப்புரிமை மீறலுக்குப் பயன்படுத்தக் கூடாது। முறையான அனுமதியின்றி பதிவிறக்கம் செய்யப்பட்ட உள்ளடக்கத்தை வணிக ரீதியாகப் பயன்படுத்துவது கண்டிப்பாகத் தடைசெய்யப்பட்டுள்ளது।\n\n5. பொறுப்பு வரம்பு\nQuick Save எந்தவிதமான உத்தரவாதங்களும் இன்றி \"உள்ளது உள்ளபடி\" வழங்கப்படுகிறது। செயலியின் பயன்பாட்டினால் ஏற்படும் தொழில்நுட்பத் தோல்விகள், தரவு இழப்பு அல்லது சட்டச் சிக்கல்களுக்கு நாங்கள் பொறுப்பல்ல।\n\n6. விதிமுறைகளில் மாற்றங்கள்\nஇந்த விதிமுறைகளை எந்த நேரத்திலும் மாற்றியமைக்கும் உரிமையை நாங்கள் கொண்டுள்ளோம்। செயலியைத் தொடர்ந்து பயன்படுத்துவது புதுப்பிக்கப்பட்ட விதிமுறைகளை ஏற்றுக்கொண்டதாகக் கருதப்படும்।',
      'privacyContent': '1. தரவு சேகரிப்பு\nஉங்கள் தனியுரிமை எங்கள் முன்னுரிமை। Quick Save-க்கு கணக்கு தேவையில்லை, மேலும் உங்கள் பெயர், மின்னஞ்சல் அல்லது இருப்பிடம் போன்ற தனிப்பட்ட தகவல்களை நாங்கள் சேகரிக்கவோ, சேமிக்கவோ அல்லது விற்கவோ மாட்டோம்।\n\n2. சாதனத்தில் செயலாக்கம்\nவீடியோ வெட்டுதல், வடிவ மாற்றம் மற்றும் உள்ளூர் வரலாற்று மேலாண்மை உள்ளிட்ட பெரும்பாலான அம்சங்கள் உங்கள் மொபைல் சாதனத்திலேயே நேரடியாகச் செயலாக்கப்படுகின்றன। உங்கள் மீடியா கோப்புகள் உங்களுக்கே தனிப்பட்டதாக இருக்கும்।\n\n3. தற்காலிக சர்வர் பயன்பாடு\nஇணைப்பு மூலம் வீடியோவைப் பதிவிறக்கும் போது, மீடியா கோப்பைப் பெறுவதற்கான கோரிக்கையை எங்கள் சர்வர் செயலாக்குகிறது। இந்தத் தரவு தற்காலிகமாகச் செயலாக்கப்பட்டு, பதிவிறக்கம் முடிந்ததும் எங்கள் சர்வர்களில் நிரந்தரமாகச் சேமிக்கப்படாது।\n\n4. அனுமதிகள்\nபதிவிறக்கம் செய்யப்பட்ட மீடியாவைச் சேமிப்பதற்கும், எடிட் செய்ய (வெட்டுதல், மாற்றுதல் போன்றவை) கோப்புகளைத் தேர்ந்தெடுக்க உங்களை அனுமதிப்பதற்கும் மட்டுமே உங்கள் புகைப்படக் கேலரி மற்றும் உள் சேமிப்பகத்திற்கான அணுகலைக் கோருகிறோம்।\n\n5. மூன்றாம் தரப்பு இணைப்புகள்\nஎங்கள் செயலியில் வெளிப்புற தளங்களுக்கான (YouTube, Instagram போன்றவை) இணைப்புகள் இருக்கலாம்। இந்த மூன்றாம் தரப்பு தளங்களின் தனியுரிமை நடைமுறைகள் அல்லது உள்ளடக்கத்திற்கு நாங்கள் பொறுப்பல்ல।\n\n6. ஒப்புதல்\nQuick Save-ஐப் பயன்படுத்துவதன் மூலம், எங்கள் தனியுரிமைக் கொள்கைக்கு நீங்கள் சம்மதிக்கிறீர்கள்।\n\n7. மூன்றாம் தரப்பு சேவைகள் மற்றும் விளம்பரம்\nவிளம்பரங்களைக் காட்டவும், செயலியின் செயல்திறனைக் கண்காணிக்கவும் Google AdMob போன்ற மூன்றாம் தரப்பு சேவைகளைப் பயன்படுத்துகிறோம். விளம்பரங்களை வழங்கவும், செயலியின் நிலைத்தன்மையை மேம்படுத்தவும் இந்த சேவைகள் உங்கள் சாதனத்தின் விளம்பர ஐடி உள்ளிட்ட அநாமதேய தரவைச் சேகரிக்கலாம்.',
    },
