      'faqQ1': 'વીડિયો કેવી રીતે ડાઉનલોડ કરવો?',
      'faqA1': 'કોઈપણ સમર્થિત પ્લેટફોર્મ પરથી વીડિયો લિંક કોપી કરો, હોમ સ્ક્રીન પર પેસ્ટ કરો અને આગળ વધો ક્લિક કરો.',
      'faqQ2': 'મેજિક ઇરેઝરનો ઉપયોગ કેવી રીતે કરવો?',
      'faqA2': 'ફોટો અથવા વીડિયો અપલોડ કરો, વોટરમાર્ક અથવા અનિચ્છનીય તત્વ પર બોક્સ દોરો અને "પસંદ કરેલ વિસ્તાર ભૂંસો" પર ક્લિક કરો.',
      'faqQ3': 'વીડિયો ટ્રિમ કેવી રીતે કરવો?',
      'faqA3': 'મીડિયા ટુલ્સ પર જાઓ, વીડિયો ટ્રિમ પસંદ કરો, તમારો વીડિયો અપલોડ કરો અને તમે જે ભાગ રાખવા માંગો છો તે પસંદ કરવા માટે સ્લાઇડર અથવા કસ્ટમ ટાઇમરનો ઉપયોગ કરો.',
      'faqQ4': 'ફાઈલ ફોર્મેટ કેવી રીતે બદલવું?',
      'faqA4': 'મીડિયા ટુલ્સમાંથી "ફોર્મેટ બદલો" પસંદ કરો, ઓડિયો અથવા વીડિયો વચ્ચે પસંદગી કરો, તમારી ફાઈલ પસંદ કરો અને MP3 અથવા MP4 જેવું લક્ષ્ય ફોર્મેટ પસંદ કરો.',
      'faqQ8': 'મારા વીડિયોમાં વોટરમાર્ક કેવી રીતે ઉમેરવો?',
      'faqA8': 'મીડિયા ટુલ્સ > વોટરમાર્ક ઉમેરો પર જાઓ, તમારો વીડિયો પસંદ કરો, ટેક્સ્ટ લખો અથવા લોગો પસંદ કરો, સ્થાન પસંદ કરો અને "વીડિયો પ્રોસેસ કરો" પર ક્લિક કરો.',
      'faqQ5': 'મારી ફાઈલો ક્યાં સેવ થાય છે?',
      'faqA5': 'વીડિયો અને ફોટા તમારી ફોટો ગેલેરીમાં સેવ થાય છે. ઓડિયો ફાઈલો "Files" એપમાં "Quick Save" ફોલ્ડરમાં મળશે.',
      'faqQ6': 'શું આ વાપરવું મફત છે?',
      'faqA6': 'હા, Quick Save વાપરવું તદ્દન મફત છે!',
      'faqQ7': 'સમર્થિત પ્લેટફોર્મ કયા છે?',
      'faqA7': 'અમે YouTube, Instagram, TikTok અને Facebook ને સપોર્ટ કરીએ છીએ.',
      'termsContent': '1. પરિચય\nQuick Save માં તમારું સ્વાગત છે। અમારી એપ્લિકેશનનો ઉપયોગ કરીને, તમે નીચેના નિયમો અને શરતોનું પાલન કરવા અને તેનાથી બંધાયેલા રહેવા માટે સંમત થાઓ છો। જો તમે સંમત ન હોવ, તો કૃપા કરીને સેવાનો ઉપયોગ કરશો નહીં।\n\n2. સેવાનું વર્ણન\nQuick Save એ એક યુટિલિટી ટૂલ છે જે વપરાશકર્તાઓને સમર્થિત પ્લેટફોર્મ પરથી વીડિયો અને ઓડિયો ડાઉનલોડ કરવા, વીડિયો ટ્રિમ કરવા, મીડિયા ફોર્મેટ બદલવા અને મેજિક ઇરેઝરનો ઉપયોગ કરીને બિનજરૂરી વસ્તુઓ દૂર કરવામાં મદદ કરવા માટે રચાયેલ છે।\n\n3. વપરાશકર્તાની જવાબદારી અને કોપીરાઈટ\nવપરાશકર્તાઓ તેઓ જે મીડિયા ડાઉનલોડ અથવા એડિટ કરે છે તેના માટે સંપૂર્ણપણે જવાબદાર છે। કોપીરાઈટવાળી સામગ્રી ડાઉનલોડ કરતા પહેલા તમારે ખાતરી કરવી જોઈએ કે તમારી પાસે સામગ્રીના માલિક પાસેથી કાયદેસરનો અધિકાર અથવા પરવાનગી છે। Quick Save કોઈપણ સામગ્રી હોસ્ટ કરતું નથી અને માત્ર ટેકનિકલ મધ્યસ્થી તરીકે કાર્ય કરે છે।\n\n4. વપરાશ પ્રતિબંધો\nતમે આ એપનો ઉપયોગ કોઈપણ ગેરકાયદેસર હેતુઓ માટે અથવા કોપીરાઈટ ઉલ્લંઘનમાં મદદ કરવા માટે કરી શકતા નથી। યોગ્ય અધિકૃતતા વિના ડાઉનલોડ કરેલી સામગ્રીનો વ્યાવસાયિક ઉપયોગ સખત પ્રતિબંધિત છે।\n\n5. જવાબદારીની મર્યાદા\nQuick Save કોઈપણ વોરંટી વિના \"જેમ છે તેમ\" પ્રદાન કરવામાં આવે છે। એપ્લિકેશનના તમારા ઉપયોગથી ઉદ્ભવતી કોઈપણ તકનીકી નિષ્ફળતા, ડેટા નુકશાન અથવા કાનૂની સમસ્યાઓ માટે અમે જવાબદાર નથી।\n\n6. શરતોમાં ફેરફાર\nઅમે કોઈપણ સમયે આ શરતોમાં ફેરફાર કરવાનો અધિકાર અનામત રાખીએ છીએ। એપનો સતત ઉપયોગ અપડેટ કરેલી શરતોની સ્વીકૃતિ ગણાશે।',
      'privacyContent': '1. ડેટા સંગ્રહ\nતમારી ગોપનીયતા અમારી પ્રાથમિકતા છે। Quick Save ને એકાઉન્ટની જરૂર નથી, અને અમે તમારું નામ, ઇમેઇલ અથવા સ્થાન જેવી કોઈ વ્યક્તિગત માહિતી એકત્રિત, સંગ્રહિત અથવા વેચતા નથી।\n\n2. ઓન-ડિવાઈસ પ્રોસેસિંગ\nવીડિયો ટ્રિમિંગ, ફોર્મેટ કન્વર્ઝન અને લોકલ હિસ્ટ્રી મેનેજમેન્ટ સહિતની મોટાભાગની સુવિધાઓ સીધી તમારા મોબાઈલ ઉપકરણ પર પ્રોસેસ કરવામાં આવે છે। તમારી મીડિયા ફાઇલો તમારા માટે ખાનગી રહે છે।\n\n3. કામચલાઉ સર્વર વપરાશ\nજ્યારે તમે લિંક દ્વારા વીડિયો ડાઉનલોડ કરો છો, ત્યારે અમારું સર્વર મીડિયા ફાઇલ મેળવવાની વિનંતી પર પ્રક્રિયા કરે છે। આ ડેટા કામચલાઉ રીતે પ્રોસેસ કરવામાં આવે છે અને ડાઉનલોડ પૂર્ણ થયા પછી અમારા સર્વ પર કાયમી ધોરણે સંગ્રહિત કરવામાં આવતો નથી।\n\n4. પરવાનગીઓ\nઅમે ડાઉનલોડ કરેલ મીડિયાને સેવ કરવા અને તમને એડિટિંગ (ટ્રિમિંગ, કન્વર્ટિંગ વગેરે) માટે ફાઇલો પસંદ કરવાની મંજૂરી આપવાના હેતુથી જ તમારી ફોટો ગેલેરી અને આંતરિક સ્ટોરેજની ઍક્સેસની વિનંતી કરીએ છીએ।\n\n5. તૃતીય-પક્ષ લિંક્સ\nઅમારી એપ્લિકેશનમાં બાહ્ય સાઇટ્સ (જેમ કે YouTube, Instagram) ની લિંક્સ હોઈ શકે છે। અમે આ તૃતીય-પક્ષ પ્લેટફોર્મની ગોપનીયતા નીતિઓ અથવા સામગ્રી માટે જવાબદાર નથી।\n\n6. સંમતિ\nQuick Save નો ઉપયોગ કરીને, તમે અમારી ગોપનીયતા નીતિ માટે સંમતિ આપો છો।\n\n7. તૃતીય-પક્ષ સેવાઓ અને જાહેરાત\nઅમે જાહેરાતો પ્રદર્શિત કરવા અને એપ્લિકેશનના પ્રદર્શનને મોનિટર કરવા માટે Google AdMob જેવી તૃતીય-પક્ષ સેવાઓનો ઉપયોગ કરીએ છીએ. આ સેવાઓ જાહેરાતો પ્રદાન કરવા અને એપ્લિકેશનની સ્થિરતા સુધારવા માટે તમારા ઉપકરણના જાહેરાત ID સહિત અનામી ડેટા એકત્રિત કરી શકે છે.',
    },
