      'faqA8': 'میڈیا ٹولز > واٹر مارک لگائیں میں جائیں، ویڈیو منتخب کریں، تحریر لکھیں یا لوگو منتخب کریں، مقام منتخب کریں اور "ویڈیو پروسیس کریں" پر کلک کریں۔',
