      'faqA7': 'ہم YouTube، Instagram، TikTok اور Facebook سپورٹ کرتے ہیں۔',
      'termsContent': '1. تعارف\nQuick Save میں خوش آمدید۔ ہماری ایپلیکیشن تک رسائی اور استعمال کر کے، آپ درج ذیل شرائط و ضوابط کی تعمیل کرنے اور ان کے پابند ہونے پر اتفاق کرتے ہیں۔ اگر آپ متفق نہیں ہیں تو براہ کرم سروس استعمال نہ کریں۔\n\n2. سروس کی تفصیل\nQuick Save ایک یوٹیلیٹی ٹول ہے جسے صارفین کو سپورٹڈ پلیٹ فارمز سے ویڈیو اور آڈیو ڈاؤن لوڈ کرنے، ویڈیوز کاٹنے، میڈیا فارمیٹ تبدیل کرنے، اور میجک ایریزر کا استعمال کرتے ہوئے ناپسندیدہ عناصر کو ہٹانے میں مدد کرنے کے لیے ڈیزائن کیا گیا ہے۔\n\n3. صارف کی ذمہ داری اور کاپی رائٹ\nصارفین اپنے ڈاؤن لوڈ یا ایڈٹ کردہ میڈیا کے خود ذمہ دار ہیں۔ آپ کو یہ یقینی بنانا چاہیے کہ کاپی رائٹ شدہ مواد ڈاؤن لوڈ کرنے سے پہلے آپ کے پاس مواد کے مالک سے قانونی حق یا اجازت موجود ہے۔ Quick Save کسی بھی مواد کی میزبانی نہیں کرتا اور صرف ایک تکنیکی بیچوان کے طور پر کام کرتا ہے۔\n\n4. استعمال کی پابندیاں\nآپ اس ایپ کو کسی بھی غیر قانونی مقاصد کے لیے یا کاپی رائٹ کی خلاف ورزی کی سہولت کے لیے استعمال نہیں کر سکتے۔ مناسب اجازت کے بغیر ڈاؤن لوڈ کردہ مواد کا تجارتی استعمال سختی سے ممنوع ہے۔\n\n5. ذمہ داری کی حد\nQuick Save بغیر کسی وارنٹی کے \"جیسا ہے\" فراہم کیا جاتا ہے۔ ہم ایپلیکیشن کے استعمال سے پیدا ہونے والی کسی بھی تکنیکی خرابی، ڈیٹا کے ضیاع، یا قانونی مسائل کے ذمہ دار نہیں ہیں۔\n\n6. شرائط میں تبدیلیاں\nہم کسی بھی وقت ان شرائط میں ترمیم کرنے کا حق محفوظ رکھتے ہیں۔ ایپ کا مسلسل استعمال اپ ڈیٹ شدہ شرائط کی قبولیت تصور کیا جائے گا۔',
      'privacyContent': '1. ڈیٹا کا مجموعہ\nآپ کی پرائیویسی ہماری ترجیح ہے۔ Quick Save کو اکاؤنٹ کی ضرورت نہیں ہے، اور ہم آپ کی ذاتی معلومات جیسے آپ کا نام، ای میل، یا مقام جمع، اسٹور یا فروخت نہیں کرتے ہیں۔\n\n2. آن ڈیوائس پروسیسنگ\nویڈیو ٹرمنگ، فارمیٹ کی تبدیلی، اور لوکل ہسٹری مینجمنٹ سمیت زیادہ تر فیچرز براہ راست آپ کے موبائل ڈیوائس پر پروسیس کیے جاتے ہیں۔ آپ کی میڈیا فائلیں آپ تک ہی محدود رہتی ہیں۔\n\n3. عارضی سرور کا استعمال\nجب آپ لنک کے ذریعے ویڈیو ڈاؤن لوڈ کرتے ہیں، تو ہمارا سرور میڈیا فائل حاصل کرنے کی درخواست پر کارروائی کرتا ہے۔ یہ ڈیٹا عارضی طور پر پروسیس کیا جاتا ہے اور ڈاؤن لوڈ مکمل ہونے کے بعد ہمارے سرورز پر مستقل طور پر اسٹور نہیں کیا جاتا ہے۔\n\n4. اجازتیں\nہم ڈاؤن لوڈ کردہ میڈیا کو محفوظ کرنے اور آپ کو ایڈیٹنگ (ٹرمنگ، کنورٹنگ وغیرہ) کے لیے فائلیں منتخب کرنے کی اجازت دینے کے مقصد کے لیے ہی آپ کی فوٹو گیلری اور انٹرنل اسٹوریج تک رسائی کی درخواست کرتے ہیں۔\n\n5. تھرڈ پارٹی لنکس\nہماری ایپ میں بیرونی سائٹس (جیسے YouTube، Instagram) کے لنکس ہو سکتے ہیں۔ ہم ان تھرڈ پارٹی پلیٹ فارمز کی پرائیویسی پالیسیوں یا مواد کے ذمہ دار نہیں ہیں۔\n\n6. رضامندی\nQuick Save استعمال کر کے، آپ ہماری پرائیویسی پالیسی سے اتفاق کرتے ہیں۔\n\n7. فریق ثالث کی خدمات اور اشتہارات\nہم اشتہارات دکھانے اور ایپ کی کارکردگی کی نگرانی کے لیے فریق ثالث کی خدمات، جیسے Google AdMob، کا استعمال کرتے ہیں۔ یہ خدمات اشتہارات فراہم کرنے اور ایپ کے استحکام کو بہتر بنانے کے لیے آپ کے آلے کی ایڈورٹائزنگ آئی ڈی سمیت گمنام ڈیٹا اکٹھا کر سکتی ہیں۔',
    },
