      'posBlurBox': 'ಬ್ಲರ್ ಬಾಕ್ಸ್ ಇರಿಸಿ',
      'faqQ1': 'ವಿಡಿಯೋ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವುದು ಹೇಗೆ?',
      'faqA1': 'ಬೆಂಬಲಿತ ಪ್ಲಾಟ್‌ಫಾರಂನಿಂದ ವಿಡಿಯೋ ಲಿಂಕ್ ಕಾಪಿ ಮಾಡಿ, ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ನಲ್ಲಿ ಪೇಸ್ಟ್ ಮಾಡಿ ಮತ್ತು ಮುಂದುವರಿಯಿರಿ ಕ್ಲಿಕ್ ಮಾಡಿ.',
      'faqQ2': 'ಮ್ಯಾಜಿಕ್ ಎರೇಸರ್ ಬಳಸುವುದು ಹೇಗೆ?',
      'faqA2': 'ಚಿತ್ರ ಅಥವಾ ವಿಡಿಯೋ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ವಾಟರ್‌ಮಾರ್ಕ್ ಅಥವಾ ಬೇಡದ ಭಾಗದ ಮೇಲೆ ಚೌಕವನ್ನು ಬಿಡಿಸಿ ಮತ್ತು "ಆಯ್ದ ಭಾಗವನ್ನು ಅಳಿಸಿ" ಕ್ಲಿಕ್ ಮಾಡಿ.',
      'faqQ3': 'ವಿಡಿಯೋ ಟ್ರಿಮ್ ಮಾಡುವುದು ಹೇಗೆ?',
      'faqA3': 'ಮೀಡಿಯಾ ಪರಿಕರಗಳಿಗೆ ಹೋಗಿ, ವಿಡಿಯೋ ಟ್ರಿಮ್ ಆಯ್ಕೆಮಾಡಿ, ವಿಡಿಯೋ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಮತ್ತು ನಿಮಗೆ ಬೇಕಾದ ಭಾಗವನ್ನು ಆಯ್ಕೆ ಮಾಡಲು ಸ್ಲೈಡರ್ ಅಥವಾ ಕಸ್ಟಮ್ ಟೈಮರ್ ಬಳಸಿ.',
      'faqQ4': 'ಫೈಲ್ ಫಾರ್ಮ್ಯಾಟ್ ಬದಲಿಸುವುದು ಹೇಗೆ?',
      'faqA4': 'ಮೀಡಿಯಾ ಪರಿಕರಗಳಿಂದ "ಫಾರ್ಮ್ಯಾಟ್ ಬದಲಿಸಿ" ಆಯ್ಕೆಮಾಡಿ, ಆಡಿಯೋ ಅಥವಾ ವಿಡಿಯೋ ಆರಿಸಿ, ನಿಮ್ಮ ಫೈಲ್ ಆರಿಸಿ ಮತ್ತು MP3 ಅಥವಾ MP4 ನಂತಹ ಫಾರ್ಮ್ಯಾಟ್ ಆರಿಸಿ.',
      'faqQ8': 'ನನ್ನ ವಿಡಿಯೋಗೆ ವಾಟರ್‌ಮಾರ್ಕ್ ಸೇರಿಸುವುದು ಹೇಗೆ?',
      'faqA8': 'ಮೀಡಿಯಾ ಪರಿಕರಗಳು > ವಾಟರ್‌ಮಾರ್ಕ್ ಸೇರಿಸಿ ಗೆ ಹೋಗಿ, ವಿಡಿಯೋ ಆರಿಸಿ, ಪಠ್ಯ ಬರೆಯಿರಿ ಅಥವಾ ಲೋಗೋ ಆರಿಸಿ, ಸ್ಥಾನ ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು "ವಿಡಿಯೋ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಿ" ಕ್ಲಿಕ್ ಮಾಡಿ.',
      'faqQ5': 'ನನ್ನ ಫೈಲ್‌ಗಳು ಎಲ್ಲಿ ಉಳಿಯುತ್ತವೆ?',
      'faqA5': 'ವಿಡಿಯೋಗಳು ಮತ್ತು ಚಿತ್ರಗಳು ನಿಮ್ಮ ಫೋಟೋ ಗ್ಯಾಲರಿಯಲ್ಲಿ ಉಳಿಯುತ್ತವೆ. ಆಡಿಯೋ ಫೈಲ್‌ಗಳು "Files" ಆ್ಯಪ್‌ನ "Quick Save" ಫೋಲ್ಡರ್‌ನಲ್ಲಿ ಇರುತ್ತವೆ.',
      'faqQ6': 'ಇದು ಉಚಿತವೇ?',
      'faqA6': 'ಹೌದು, Quick Save ಬಳಸುವುದು ಸಂಪೂರ್ಣ ಉಚಿತ!',
      'faqQ7': 'ಯಾವ ಪ್ಲಾಟ್‌ಫಾರಂಗಳು ಬೆಂಬಲಿತವಾಗಿವೆ?',
      'faqA7': 'ನಾವು YouTube, Instagram, TikTok ಮತ್ತು Facebook ಅನ್ನು ಬೆಂಬಲಿಸುತ್ತೇವೆ.',
      'termsContent': '1. ಪೀಠಿಕೆ\nQuick Save ಗೆ ಸುಸ್ವಾಗತ. ನಮ್ಮ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಪ್ರವೇಶಿಸುವ ಮತ್ತು ಬಳಸುವ ಮೂಲಕ, ನೀವು ಈ ಕೆಳಗಿನ ನಿಯಮಗಳು ಮತ್ತು ನಿಬಂಧನೆಗಳನ್ನು ಪಾಲಿಸಲು ಒಪ್ಪುತ್ತೀರಿ. ನೀವು ಒಪ್ಪದಿದ್ದರೆ, ದಯವಿಟ್ಟು ಸೇವೆಯನ್ನು ಬಳಸಬೇಡಿ.\n\n2. ಸೇವೆಯ ವಿವರಣೆ\nQuick Save ಎನ್ನುವುದು ಬೆಂಬಲಿತ ವೇದಿಕೆಗಳಿಂದ ವಿಡಿಯೋ ಮತ್ತು ಆಡಿಯೊವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಲು, ವಿಡಿಯೋಗಳನ್ನು ಟ್ರಿಮ್ ಮಾಡಲು, ಮೀಡಿಯಾ ಫಾರ್ಮ್ಯಾಟ್‌ಗಳನ್ನು ಬದಲಾಯಿಸಲು ಮತ್ತು ಮ್ಯಾಜಿಕ್ ಎರೇಸರ್ ಬಳಸಿ ಬೇಡದ ಅಂಶಗಳನ್ನು ತೆಗೆದುಹಾಕಲು ಬಳಕೆದಾರರಿಗೆ ಸಹಾಯ ಮಾಡಲು ವಿನ್ಯಾಸಗೊಳಿಸಲಾದ ಒಂದು ಉಪಯುಕ್ತ ಸಾಧನವಾಗಿದೆ.\n\n3. ಬಳಕೆದಾರರ ಜವಾಬ್ದಾರಿ ಮತ್ತು ಹಕ್ಕುಸ್ವಾಮ್ಯ\nಬಳಕೆದಾರರು ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಅಥವಾ ಎಡಿಟ್ ಮಾಡುವ ಮೀಡಿಯಾಕ್ಕೆ ಅವರೇ ಸಂಪೂರ್ಣ ಜವಾಬ್ದಾರರು. ಹಕ್ಕುಸ್ವಾಮ್ಯ ಹೊಂದಿರುವ ವಿಷಯವನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡುವ ಮೊದಲು ನೀವು ವಿಷಯದ ಮಾಲೀಕರಿಂದ ಕಾನೂನುಬದ್ಧ ಹಕ್ಕು ಅಥವಾ ಅನುಮತಿಯನ್ನು ಹೊಂದಿದ್ದೀರಿ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಬೇಕು. Quick Save ಯಾವುದೇ ವಿಷಯವನ್ನು ಹೋಸ್ಟ್ ಮಾಡುವುದಿಲ್ಲ ಮತ್ತು ಕೇವಲ ತಾಂತ್ರಿಕ ಮಧ್ಯವರ್ತಿಯಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.\n\n4. ಬಳಕೆಯ ನಿರ್ಬಂಧಗಳು\nನೀವು ಈ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಯಾವುದೇ ಕಾನೂನುಬಾಹಿರ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಅಥವಾ ಹಕ್ಕುಸ್ವಾಮ್ಯ ಉಲ್ಲಂಘನೆಗೆ ಬಳಸಬಾರದು. ಸರಿಯಾದ ಅನುಮತಿಯಿಲ್ಲದೆ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ ವಿಷಯವನ್ನು ವಾಣಿಜ್ಯಿಕವಾಗಿ ಬಳಸುವುದನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ನಿಷೇಧಿಸಲಾಗಿದೆ.\n\n5. ಹೊಣೆಗಾರಿಕೆಯ ಮಿತಿ\nQuick Save ಅನ್ನು ಯಾವುದೇ ಖಾತರಿಗಳಿಲ್ಲದೆ \"ಇದ್ದಂತೆಯೇ\" ಒದಗಿಸಲಾಗಿದೆ. ಅಪ್ಲಿಕೇಶನ್ ಬಳಕೆಯಿಂದ ಉಂಟಾಗುವ ಯಾವುದೇ ತಾಂತ್ರಿಕ ವೈಫಲ್ಯಗಳು, ಡೇಟಾ ನಷ್ಟ ಅಥವಾ ಕಾನೂನು ಸಮಸ್ಯೆಗಳಿಗೆ ನಾವು ಜವಾಬ್ದಾರರಲ್ಲ.\n\n6. ನಿಯಮಗಳಲ್ಲಿ ಬದಲಾವಣೆ\nಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಈ ನಿಯಮಗಳನ್ನು ಬದಲಾಯಿಸುವ ಹಕ್ಕನ್ನು ನಾವು ಹೊಂದಿದ್ದೇವೆ. ಅಪ್ಲಿಕೇಶನ್‌ನ ಮುಂದುವರಿಸಿದ ಬಳಕೆಯು ನವೀಕರಿಸಿದ ನಿಯಮಗಳನ್ನು ಒಪ್ಪಿಕೊಂಡಂತೆ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ.',
      'privacyContent': '1. ಡೇಟಾ ಸಂಗ್ರಹಣೆ\nನಿಮ್ಮ ಗೌಪ್ಯತೆ ನಮ್ಮ ಆದ್ಯತೆಯಾಗಿದೆ. Quick Save ಗೆ ಯಾವುದೇ ಖಾತೆಯ ಅಗತ್ಯವಿಲ್ಲ ಮತ್ತು ನಿಮ್ಮ ಹೆಸರು, ಇಮೇಲ್ ಅಥವಾ ಸ್ಥಳದಂತಹ ಯಾವುದೇ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ನಾವು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ, ಉಳಿಸುವುದಿಲ್ಲ ಅಥವಾ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ.\n\n2. ಸಾಧನದಲ್ಲಿ ಸಂಸ್ಕರಣೆ\nವಿಡಿಯೋ ಟ್ರಿಮ್ಮಿಂಗ್, ಫಾರ್ಮ್ಯಾಟ್ ಪರಿವರ್ತನೆ ಮತ್ತು ಸ್ಥಳೀಯ ಇತಿಹಾಸ ನಿರ್ವಹಣೆ ಸೇರಿದಂತೆ ಹೆಚ್ಚಿನ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ನಿಮ್ಮ ಮೊಬೈಲ್ ಸಾಧನದಲ್ಲಿಯೇ ನೇರವಾಗಿ ಸಂಸ್ಕರಿಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಮೀಡಿಯಾ ಫೈಲ್‌ಗಳು ನಿಮಗೇ ಖಾಸಗಿಯಾಗಿರುತ್ತವೆ.\n\n3. ತಾತ್ಕಾಲಿಕ ಸರ್ವರ್ ಬಳಕೆ\nನೀವು ಲಿಂಕ್ ಮೂಲಕ ವಿಡಿಯೋ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದಾಗ, ಮೀಡಿಯಾ ಫೈಲ್ ಅನ್ನು ಪಡೆಯಲು ನಮ್ಮ ಸರ್ವರ್ ವಿನಂತಿಯನ್ನು ಸಂಸ್ಕರಿಸುತ್ತದೆ. ಈ ಡೇಟಾವನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಸಂಸ್ಕರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಡೌನ್‌ಲೋಡ್ ಪೂರ್ಣಗೊಂಡ ನಂತರ ನಮ್ಮ ಸರ್ವರ್‌ಗಳಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುವುದಿಲ್ಲ.\n\n4. ಅನುಮತಿಗಳು\nಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ ಮೀಡಿಯಾವನ್ನು ಉಳಿಸಲು ಮತ್ತು ಎಡಿಟಿಂಗ್ (ಟ್ರಿಮ್ಮಿಂಗ್, ಕನ್ವರ್ಟಿಂಗ್ ಇತ್ಯಾದಿ) ಗಾಗಿ ಫೈಲ್‌ಗಳನ್ನು ಆಯ್ಕೆ ಮಾಡಲು ನಿಮಗೆ ಅನುಮತಿಸುವ ಉದ್ದೇಶದಿಂದ ಮಾತ್ರ ನಾವು ನಿಮ್ಮ ಫೋಟೋ ಗ್ಯಾಲರಿ ಮತ್ತು ಆಂತರಿಕ ಸಂಗ್ರಹಣೆಗೆ ಪ್ರವೇಶವನ್ನು ವಿನಂತಿಸುತ್ತೇವೆ.\n\n5. ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಲಿಂಕ್‌ಗಳು\nನಮ್ಮ ಅಪ್ಲಿಕೇಶನ್ ಬಾಹ್ಯ ಸೈಟ್‌ಗಳ (YouTube, Instagram ನಂತಹ) ಲಿಂಕ್‌ಗಳನ್ನು ಹೊಂದಿರಬಹುದು. ಈ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ವೇದಿಕೆಗಳ ಗೌಪ್ಯತೆ ಅಭ್ಯಾಸಗಳು ಅಥವಾ ವಿಷಯಕ್ಕೆ ನಾವು ಜವಾಬ್ದಾರರಲ್ಲ.\n\n6. ಸಮ್ಮತಿ\nQuick Save ಬಳಸುವ ಮೂಲಕ, ನೀವು ನಮ್ಮ ಗೌಪ್ಯತಾ ನೀತಿಯನ್ನು ಒಪ್ಪುತ್ತೀರಿ.\n\n7. ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಸೇವೆಗಳು ಮತ್ತು ಜಾಹೀರಾತು\nಜಾಹೀರಾತುಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲು ನಾವು Google AdMob ನಂತಹ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಸೇವೆಗಳನ್ನು ಬಳಸುತ್ತೇವೆ. ಜಾಹೀರಾತುಗಳನ್ನು ಒದಗಿಸಲು ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್ ಸ್ಥಿರತೆಯನ್ನು ಸುಧಾರಿಸಲು ಈ ಸೇವೆಗಳು ನಿಮ್ಮ ಸಾಧನದ ಜಾಹೀರಾತು ಐಡಿ ಸೇರಿದಂತೆ ಅನಾಮಧೇಯ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸಬಹುದು.',
    },
