      'posBlurBox': 'ବ୍ଲର୍ ବକ୍ସ ସଜାନ୍ତୁ',
      'faqQ1': 'ଭିଡିଓ କିପରି ଡାଉନଲୋଡ୍ କରିବେ?',
      'faqA1': 'ଯେକୌଣସି ସପୋର୍ଟେଡ୍ ପ୍ଲାଟଫର୍ମରୁ ଭିଡିଓ ଲିଙ୍କ୍ କପି କରନ୍ତୁ, ହୋମ୍ ସ୍କ୍ରିନରେ ପେଷ୍ଟ୍ କରନ୍ତୁ ଏବଂ କଣ୍ଟିନ୍ୟୁ କ୍ଲିକ୍ କରନ୍ତୁ।',
      'faqQ2': 'ମ୍ୟାଜିକ୍ ଇରେଜର କିପରି ବ୍ୟବହାର କରିବେ?',
      'faqA2': 'ଫଟୋ କିମ୍ବା ଭିଡିଓ ଅପଲୋଡ୍ କରନ୍ତୁ, ୱାଟରମାର୍କ କିମ୍ବା ଅଦରକାରୀ ଜିନିଷ ଉପରେ ବକ୍ସ ତିଆରି କରନ୍ତୁ ଏବଂ "ସିଲେକ୍ଟ ହୋଇଥିବା ଅଂଶ ଲିଭାନ୍ତୁ" କ୍ଲିକ୍ କରନ୍ତୁ।',
      'faqQ3': 'ଭିଡିଓ କିପରି ଟ୍ରିମ୍ କରିବେ?',
      'faqA3': 'ମିଡିଆ ଟୁଲ୍ସକୁ ଯାଆନ୍ତୁ, ଟ୍ରିମ୍ ଭିଡିଓ ବାଛନ୍ତୁ, ଆପଣଙ୍କ ଭିଡିଓ ଅପଲୋଡ୍ କରନ୍ତୁ ଏବଂ ଯେଉଁ ଅଂଶ ରଖିବାକୁ ଚାହୁଁଛନ୍ତି ତାହା ବାଛିବା ପାଇଁ ସ୍ଲାଇଡର୍ କିମ୍ବା ଟାଇମର୍ ବ୍ୟବହାର କରନ୍ତୁ।',
      'faqQ4': 'ଫାଇଲ୍ ଫର୍ମାଟ୍ କିପରି ବଦଳାଇବେ?',
      'faqA4': 'ମିଡିଆ ଟୁଲ୍ସରୁ "ଫର୍ମାଟ୍ ବଦଳାନ୍ତୁ" ବାଛନ୍ତୁ, ଅଡିଓ କିମ୍ବା ଭିଡିଓ ମଧ୍ୟରୁ ଗୋଟିଏ ବାଛନ୍ତୁ, ଆପଣଙ୍କ ଫାଇଲ୍ ବାଛନ୍ତୁ ଏବଂ MP3 କିମ୍ବା MP4 ଭଳି ଫର୍ମାଟ୍ ବାଛନ୍ତୁ।',
      'faqQ8': 'ମୋ ଭିଡିଓରେ ୱାଟରମାର୍କ କିପରି ଲଗାଇବି?',
      'faqA8': 'ମିଡିଆ ଟୁଲ୍ସ > ୱାଟରମାର୍କ ଲଗାନ୍ତୁ କୁ ଯାଆନ୍ତୁ, ଭିଡିଓ ବାଛନ୍ତୁ, ଲେଖା ଲେଖନ୍ତୁ କିମ୍ବା ଲୋଗୋ ବାଛନ୍ତୁ, ସ୍ଥିତି ବାଛନ୍ତୁ ଏବଂ "ପ୍ରୋସେସ୍ ଭିଡିଓ" କ୍ଲିକ୍ କರନ୍ତୁ।',
      'faqQ5': 'ମୋର ଫାଇଲ୍ ଗୁଡିକ କେଉଁଠି ସେଭ୍ ହୁଏ?',
      'faqA5': 'ଭିଡିଓ ଏବଂ ଫଟୋ ଆପଣଙ୍କ ଫଟୋ ଗ୍ୟାଲେରୀରେ ସେଭ୍ ହୁଏ। ଅଡିଓ ଫାଇଲ୍ ଗୁଡିକ "Files" ଆପରେ "Quick Save" ଫୋଲଡର୍ ମଧ୍ୟରେ ମିଳିବ।',
      'faqQ6': 'ଏହା ବ୍ୟବହାର କରିବା ମାଗଣା କି?',
      'faqA6': 'ହଁ, Quick Save ବ୍ୟବହାର କରିବା ସମ୍ପୂର୍ଣ୍ଣ ମାଗଣା!',
      'faqQ7': 'କେଉଁ ସବୁ ପ୍ଲାଟଫର୍ମ ସପୋର୍ଟେଡ୍?',
      'faqA7': 'ଆମେ YouTube, Instagram, TikTok ଏବଂ Facebook ସପୋର୍ଟ କରୁ।',
      'termsContent': '1. ଉପକ୍ରମଣିକା\nQuick Save କୁ ସ୍ୱାଗତ। ଆମର ଆପ୍ଲିକେସନ୍ ବ୍ୟବହାର କରିବା ଦ୍ୱାରା, ଆପଣ ନିମ୍ନଲିଖିତ ନିୟମ ଏବଂ ସର୍ତ୍ତାବଳୀ ପାଳନ କରିବାକୁ ସହମତ ଅଟନ୍ତି। ଯଦି ଆପଣ ସହମତ ନୁହଁନ୍ତି, ତେବେ ଦୟାକରି ସେବା ବ୍ୟବହାର କରନ୍ତୁ ନାହିଁ।\n\n2. ସେବା ବିବରଣୀ\nQuick Save ହେଉଛି ଏକ ଉପଯୋଗୀ ସାଧନ ଯାହା ବ୍ୟବହାରକାରୀଙ୍କୁ ସମର୍ଥିତ ପ୍ଲାଟଫର୍ମରୁ ଭିଡିଓ ଏବଂ ଅଡିଓ ଡାଉନଲୋଡ୍ କରିବା, ଭିଡିଓ ଟ୍ରିମ୍ କରିବା, ମିଡିଆ ଫର୍ମାଟ୍ ବଦଳାଇବା ଏବଂ ମ୍ୟାଜିକ୍ ଇରେଜର ବ୍ୟବହાર କରି ଅଦରକାରୀ ଜିନିଷ ହଟାଇବାରେ ସାହାଯ୍ୟ କରେ।\n\n3. ବ୍ୟବହାରକାରୀଙ୍କ ଦାୟିତ୍ୱ ଏବଂ କପିରାଇଟ୍\nବ୍ୟବହାରକାରୀମାନେ ସେମାନଙ୍କ ଦ୍ୱାରା ଡାଉନଲୋଡ୍ କିମ୍ବା ଏଡିଟ୍ କରାଯାଇଥିବା ମିଡିଆ ପାଇଁ ନିଜେ ଦାୟୀ। କପିରାଇଟ୍ ଥିବା ସାମଗ୍ରୀ ଡାଉନଲୋଡ୍ କରିବା ପୂର୍ବରୁ ଆପଣଙ୍କ ପାଖରେ ମାଲିକଙ୍କ ଆଇନଗତ ଅନୁମତି ଅଛି କି ନାହିଁ ତାହା ନିଶ୍ଚିତ କରନ୍ତୁ। Quick Save କୌଣସି ସାମଗ୍ରୀ ହୋଷ୍ଟ କରେ ନାହିଁ ଏବଂ କେବଳ ଏକ ବୈଷୟିକ ମଧ୍ୟସ୍ଥି ଭାବରେ କାର୍ଯ୍ୟ କରେ।\n\n4. ବ୍ୟବହାର ପ୍ରତିବନ୍ଧକ\nଆପଣ ଏହି ଆପକୁ କୌଣସି ବେଆଇନ କାର୍ଯ୍ୟ କିମ୍ବା କପିରାଇଟ୍ ଉଲ୍ଲଂଘନ ପାଇଁ ବ୍ୟବହାର କରିପାରିବେ ନାହିଁ। ବିନା ଅନୁମତିରେ ଡାଉନଲୋଡ୍ ହୋଇଥିବା ବିଷୟବସ୍ତୁର ବ୍ୟବସାୟିକ ବ୍ୟବହାର ନିଷେଧ।\n\n5. ଦାୟିତ୍ୱର ସୀମା\nQuick Save କୌଣସି ୱାରେଣ୍ଟି ବିନା \"ଯେମିତି ଅଛି\" ଭାବରେ ପ୍ରଦାନ କରାଯାଇଛି। ଆପ୍ଲିକେସନ୍ ବ୍ୟବହାର ଯୋଗୁଁ ହେଉଥିବା କୌଣସି ବୈଷୟିକ ତ୍ରୁଟି କିମ୍ବା ଡାଟା ହାନି ପାଇଁ ଆମେ ଦାୟୀ ନୁହଁ।\n\n6. ସର୍ତ୍ତାବଳୀରେ ପରିବର୍ତ୍ତନ\nଆମେ ଯେକୌଣସି ସମୟରେ ଏହି ସର୍ତ୍ତାବଳୀକୁ ସଂଶୋધନ କରିବାର ଅଧିକାର ରଖୁ। ଆପର ନିରନ୍ତર ବ୍ୟବହାରକୁ ସଂଶୋଧିତ ସର୍ତ୍ତାବଳୀର ସ୍ୱୀକୃତି ବୋଲି ଧରାଯିବ।',
      'privacyContent': '1. ଡାଟା ସଂଗ୍ରହ\nଆପଣଙ୍କ ଗୋପନୀୟତା ଆମର ପ୍ରାଥମିକତା। Quick Save ପାଇଁ କୌଣସି ଆକାଉଣ୍ଟ ଆବଶ୍ୟક ନାହିଁ ଏବଂ ଆମେ ଆପଣଙ୍କ ନାମ, ଇମେଲ୍ କିମ୍ବା ସ୍ଥାନ ଭଳି କୌଣସି ବ୍ୟକ୍ତିଗତ ସୂଚନା ସଂଗ୍ରહ କିମ୍ବା ବିକ୍ରି କରୁନାହୁଁ।\n\n2. ଡିଭାଇସରେ ପ୍ରୋସେସିଂ\nଭିଡିଓ ଟ୍ରିମିଂ, ଫର୍ମାଟ୍ ପରିବର୍ତ୍ତନ ଏବଂ ଇତିହାସ ପରିଚାଳନା ସହିତ ଅଧିକାଂଶ ବୈଶିଷ୍ଟ୍ୟ ସିଧାସଳଖ ଆପଣଙ୍କ ମୋବାଇଲ୍ ଡିଭାଇସରେ ପ୍ରୋସେସ୍ ହୁଏ। ଆପଣଙ୍କ ମିଡିଆ ଫାଇଲ୍ ଗୁଡିକ ଆପଣଙ୍କ ପାଖରେ ସୁରକ୍ଷିତ ରହେ।\n\n3. ଅସ୍ଥାୟୀ ସର୍ଭର ବ୍ୟବହାର\nଯେତେବେଳେ ଆପଣ ଲିଙ୍କ୍ ମାଧ୍ୟମରେ ଏକ ଭିଡିଓ ଡାଉନଲୋଡ୍ କରନ୍ତି, ଆମର ସର୍ଭର ସେହି ଅନୁରୋଧକୁ ପ୍ରୋସେସ୍ କରେ। ଏହି ଡାଟା ଅସ୍ଥାୟୀ ଭାବରେ ପ୍ରୋସେସ୍ ହୁଏ ଏବଂ ଡାଉନଲୋଡ୍ ସରିବା ପରେ ଆମ ସର୍ଭରରେ ସବୁଦିନ ପାଇଁ ରହେ ନାହିଁ।\n\n4. ଅନୁମତି\nଆମେ ଡାଉନଲୋଡ୍ ହୋଇଥିବା ମିଡିଆକୁ ସେଭ୍ କରିବା ଏବଂ ଏଡିଟିଂ ପାଇଁ ଫାଇଲ୍ ବାଛିବା ପାଇଁ ଆପଣଙ୍କ ଗ୍ୟାଲେରୀ ଏବଂ ଇଣ୍ଟରନାଲ୍ ଷ୍ଟୋରେଜ୍ ର ଅନୁମତି ମାଗିଥାଉ।\n\n5. ତୃତୀୟ ପକ୍ଷ ଲିଙ୍କ୍\nଆମ ଆପରେ ବାହାର ସାଇଟ୍ (YouTube, Instagram) ର ଲિଙ୍କ୍ ଥାଇପାରେ। ସେହି ସବୁ ସାଇଟର ଗୋପନୀયତା ନୀତି ପାଇଁ ଆମେ ଦାୟୀ ନୁହଁ।\n\n6. ସମ୍ମତି\nQuick Save ବ୍ୟବହାର କରିବା ଦ୍ୱାରा, ଆପଣ ଆମର ଗୋପନୀયତା ନୀତି ସହିତ ସହମତ ଅଟନ୍ତି।\n\n7. ତୃତୀୟ-ପକ୍ଷ ସେବା ଏବଂ ବିଜ୍ଞାପନ\nବିଜ୍ଞାପନ ପ୍ରଦର୍ଶନ କରିବା ଏବଂ ଆପ୍ କାର୍ଯ୍ୟଦକ୍ଷତା ଉପରେ ନଜର ରଖିବା ପାଇଁ ଆମେ Google AdMob ଭଳି ତୃତୀୟ-ପକ୍ଷ ସେବାଗୁଡିକ ବ୍ୟବହାର କରୁ। ବିଜ୍ଞାପନ ପ୍ରଦାନ କରିବା ଏବଂ ଆପ୍ ସ୍ଥିରତାକୁ ଉନ୍ନତ କରିବା ପାଇଁ ଏହି ସେବାଗୁଡିକ ଆପଣଙ୍କ ଡିଭାଇସ୍ ର ବିଜ୍ଞାପନ ID ସହିତ ଅଜ୍ଞାତ ଡାଟା ସଂଗ୍ରହ କରିପାରନ୍ତି।',
    },
