      'posBlurBox': 'ബ്ലർ ബോക്സ് ക്രമീകരിക്കുക',
      'faqQ1': 'വീഡിയോ എങ്ങനെ ഡൗൺലോഡ് ചെയ്യാം?',
      'faqA1': 'പിന്തുണയുള്ള ഏതെങ്കിലും പ്ലാറ്റ്‌ഫോമിൽ നിന്ന് വീഡിയോ ലിങ്ക് കോപ്പി ചെയ്യുക, ഹോം സ്‌ക്രീനിൽ പേസ്റ്റ് ചെയ്യുക, തുടർന്ന് തുടരുക ക്ലിക് ചെയ്യുക.',
      'faqQ2': 'മാജിക് ഇറേസർ എങ്ങനെ ഉപയോഗിക്കാം?',
      'faqA2': 'ഒരു ചിത്രമോ വീഡിയോയോ അപ്‌ലോഡ് ചെയ്യുക, വാട്ടർമാർക്കിന് മുകളിലോ അനാവശ്യ ഭാഗത്തോ ഒരു ബോക്സ് വരയ്ക്കുക, തുടർന്ന് "തിരഞ്ഞെടുത്ത ഭാഗം മായ്ക്കുക" ക്ലിക് ചെയ്യുക.',
      'faqQ3': 'വീഡിയോ എങ്ങനെ ട്രിം ചെയ്യാം?',
      'faqA3': 'മീഡിയ ടൂളുകളിൽ പോയി, ട്രിം വീഡിയോ തിരഞ്ഞെടുക്കുക, നിങ്ങളുടെ വീഡിയോ അപ്‌ലോഡ് ചെയ്യുക, നിങ്ങൾക്ക് ആവശ്യമുള്ള ഭാഗം തിരഞ്ഞെടുക്കാൻ സ്ലൈഡറോ കസ്റ്റം ടൈമറോ ഉപയോഗിക്കുക.',
      'faqQ4': 'ഫയൽ ഫോർമാറ്റുകൾ എങ്ങനെ മാറ്റാം?',
      'faqA4': 'മീഡിയ ടൂളുകളിൽ നിന്ന് "ഫോർമാറ്റ് മാറ്റുക" തിരഞ്ഞെടുക്കുക, ഓഡിയോ അല്ലെങ്കിൽ വീഡിയോ തിരഞ്ഞെടുക്കുക, നിങ്ങളുടെ ഫയൽ തിരഞ്ഞെടുക്കുക, തുടർന്ന് MP3 അല്ലെങ്കിൽ MP4 പോലുള്ള ലക്ഷ്യ ഫോർമാറ്റ് തിരഞ്ഞെടുക്കുക.',
      'faqQ8': 'വീഡിയോയിൽ എങ്ങനെ വാട്ടർമാർക്ക് ചേർക്കാം?',
      'faqA8': 'മീഡിയ ടൂളുകൾ > വാട്ടർമാർക്ക് ചേർക്കുക എന്നതിൽ പോയി, വീഡിയോ തിരഞ്ഞെടുക്കുക, ടെക്സ്റ്റ് നൽകുക അല്ലെങ്കിൽ ലോഗോ തിരഞ്ഞെടുക്കുക, സ്ഥാനം തിരഞ്ഞെടുത്ത് "വീഡിയോ പ്രോസസ്സ് ചെയ്യുക" ക്ലിക് ചെയ്യുക.',
      'faqQ5': 'എന്റെ ഫയലുകൾ എവിടെയാണ് സേവ് ആകുന്നത്?',
      'faqA5': 'വീഡിയോകളും ചിത്രങ്ങളും നിങ്ങളുടെ ഫോട്ടോ ഗാലറിയിൽ സേവ് ചെയ്യപ്പെടും. ഓഡിയോ ഫയലുകൾ "Files" ആപ്പിലെ "Quick Save" ഫോൾഡറിൽ കാണാം.',
      'faqQ6': 'ഇത് ഉപയോഗിക്കുന്നത് സൗജന്യമാണോ?',
      'faqA6': 'അതെ, Quick Save ഉപയോഗിക്കുന്നത് പൂർണ്ണമായും സൗജന്യമാണ്!',
      'faqQ7': 'പിന്തുണയ്ക്കുന്ന പ്ലാറ്റ്‌ഫോമുകൾ ഏതെല്ലാം?',
      'faqA7': 'ഞങ്ങൾ YouTube, Instagram, TikTok, Facebook എന്നിവയെ പിന്തുണയ്ക്കുന്നു.',
      'termsContent': '1. ആമുഖം\nQuick Save-ലേക്ക് സ്വാഗതം. ഞങ്ങളുടെ ആപ്ലിക്കേഷൻ ഉപയോഗിക്കുന്നതിലൂടെ, താഴെ പറയുന്ന നിബന്ധനകളും വ്യവസ്ഥകളും പാലിക്കാൻ നിങ്ങൾ സമ്മതിക്കുന്നു. നിങ്ങൾ സമ്മതിക്കുന്നില്ലെങ്കിൽ, ദയവായി സേവനം ഉപയോഗിക്കരുത്.\n\n2. സേവന വിവരണം\nപിന്തുണയുള്ള പ്ലാറ്റ്‌ഫോമുകളിൽ നിന്ന് വീഡിയോയും ഓഡിയോയും ഡൗൺലോഡ് ചെയ്യാനും, വീഡിയോകൾ ട്രിം ചെയ്യാനും, മീഡിയ ഫോർമാറ്റുകൾ മാറ്റാനും, മാജിക് ഇറേസർ ഉപയോഗിച്ച് അനാവശ്യ ഘടകങ്ങൾ നീക്കം ചെയ്യാനും സഹായിക്കുന്ന ഒരു യൂട്ടിലിറ്റി ടൂളാണ് Quick Save.\n\n3. ഉപയോക്താവിന്റെ ഉത്തരവാദിത്തവും പകർപ്പവകാശവും\nഉപയോക്താക്കൾ ഡൗൺലോഡ് ചെയ്യുന്നതോ എഡിറ്റ് ചെയ്യുന്നതോ ആയ മീഡിയയുടെ പൂർണ്ണ ഉത്തരവാദിത്തം അവർക്ക് മാത്രമായിരിക്കും. പകർപ്പവകാശമുള്ള ഉള്ളടക്കം ഡൗൺലോഡ് ചെയ്യുന്നതിന് മുമ്പ് നിങ്ങൾക്ക് ഉടമയിൽ നിന്ന് നിയമപരമായ അവകാശമോ അനുമതിയോ ഉണ്ടെന്ന് ഉറപ്പാക്കണം. Quick Save ഉള്ളടക്കങ്ങളൊന്നും ഹോസ്റ്റ് ചെയ്യുന്നില്ല, കേവലം ഒരു സാങ്കേതിക ഇടനിലക്കാരനായി മാത്രം പ്രവർത്തിക്കുന്നു.\n\n4. ഉപയോഗ നിയന്ത്രണങ്ങൾ\nനിയമവിരുദ്ധമായ ആവശ്യങ്ങൾക്കോ പകർപ്പവകാശ ലംഘനത്തിനോ ഈ ആപ്പ് ഉപയോഗിക്കാൻ പാടില്ല. മതിയായ അനുമതിയില്ലാതെ ഡൗൺലോഡ് ചെയ്ത ഉള്ളടക്കം വാണിജ്യ ആവശ്യങ്ങൾക്കായി ഉപയോഗിക്കുന്നത് കർശനമായി നിരോധിച്ചിരിക്കുന്നു.\n\n5. ബാധ്യതയുടെ പരിധി\nQuick Save \"അതുപോലെ തന്നെ\" (as is) ലഭ്യമാക്കുന്നു. ആപ്ലിക്കേഷന്റെ ഉപയോഗം മൂലമുണ്ടാകുന്ന സാങ്കേതിക തകരാറുകൾക്കോ ഡാറ്റാ നഷ്ടത്തിനോ നിയമപരമായ പ്രശ്നങ്ങൾക്കോ ഞങ്ങൾ ഉത്തരവാദികളല്ല.\n\n6. നിബന്ധനകളിലെ മാറ്റങ്ങൾ\nഏത് സമയത്തും ഈ നിബന്ധനകൾ പരിഷ്കരിക്കാനുള്ള അവകാശം ഞങ്ങളിൽ നിക്ഷിപ്തമാണ്. ആപ്പിന്റെ തുടർന്നുള്ള ഉപയോഗം പുതുക്കിയ നിബന്ധനകൾ അംഗീകരിച്ചതായി കണക്കാക്കും.',
      'privacyContent': '1. ഡാറ്റ ശേഖരണം\nനിങ്ങളുടെ സ്വകാര്യതയ്ക്കാണ് ഞങ്ങൾ മുൻഗണന നൽകുന്നത്. Quick Save-ന് അക്കൗണ്ട് ആവശ്യമില്ല, നിങ്ങളുടെ പേര്, ഇമെയിൽ അല്ലെങ്കിൽ ലൊക്കേഷൻ തുടങ്ങിയ വ്യക്തിഗത വിവരങ്ങളൊന്നും ഞങ്ങൾ ശേഖരിക്കുകയോ വിൽക്കുകയോ ചെയ്യുന്നില്ല.\n\n2. ഉപകരണത്തിലെ പ്രോസസ്സിംഗ്\nവീഡിയോ ട്രിമ്മിംഗ്, ഫോർമാറ്റ് മാറ്റം, ലോക്കൽ ഹിസ്റ്ററി മാനേജ്‌മെന്റ് എന്നിവയുൾപ്പെടെയുള്ള മിക്ക ഫീച്ചറുകളും നിങ്ങളുടെ മൊബൈൽ ഉപകരണത്തിൽ നേരിട്ട് പ്രോസസ്സ് ചെയ്യുന്നു. നിങ്ങളുടെ മീഡിയ ഫയലുകൾ സ്വകാര്യമായി തുടരുന്നു.\n\n3. താൽക്കാലിക സെർവർ ഉപയോഗം\nലിങ്ക് വഴി ഒരു വീഡിയോ ഡൗൺലോഡ് ചെയ്യുമ്പോൾ, മീഡിയ ഫയൽ ലഭിക്കുന്നതിനുള്ള അഭ്യർത്ഥന ഞങ്ങളുടെ സെർവർ പ്രോസസ്സ് ചെയ്യുന്നു. ഈ ഡാറ്റ താൽക്കാലികമായി മാത്രമേ ഉപയോഗിക്കുന്നുള്ളൂ, ഡൗൺലോഡ് പൂർത്തിയായ ശേഷം സെർവറിൽ സൂക്ഷിക്കില്ല.\n\n4. അനുമതികൾ\nഡൗൺലോഡ് ചെയ്ത മീഡിയ സേവ് ചെയ്യാനും എഡിറ്റിംഗിനായി ഫയലുകൾ തിരഞ്ഞെടുക്കാനും അനുവദിക്കുന്നതിനായി മാത്രമാണ് ഞങ്ങൾ നിങ്ങളുടെ ഫോട്ടോ ഗാലറിയിലേക്കും ഇന്റേണൽ സ്റ്റോറേജിലേക്കും പ്രവേശനം ആവശ്യപ്പെടുന്നത്.\n\n5. തേർഡ് പാർട്ടി ലിങ്കുകൾ\nഞങ്ങളുടെ ആപ്പിൽ ബാഹ്യ സൈറ്റുകളുടെ (YouTube, Instagram പോലുള്ളവ) ലിങ്കുകൾ ഉണ്ടായേക്കാം. ഈ തേർഡ് പാർട്ടി പ്ലാറ്റ്‌ഫോമുകളുടെ സ്വകാര്യതാ നയങ്ങൾക്കോ ഉള്ളടക്കത്തിനോ ഞങ്ങൾ ഉത്തരവാദികളല്ല.\n\n6. സമ്മതം\nQuick Save ഉപയോഗിക്കുന്നതിലൂടെ, ഞങ്ങളുടെ സ്വകാര്യതാ നയം നിങ്ങൾ അംഗീകരിക്കുന്നു.\n\n7. മൂന്നാം കക്ഷി സേവനങ്ങളും പരസ്യവും\nപരസ്യങ്ങൾ പ്രദർശിപ്പിക്കുന്നതിനും ആപ്പ് പ്രകടനം നിരീക്ഷിക്കുന്നതിനും ഞങ്ങൾ Google AdMob പോലുള്ള മൂന്നാം കക്ഷി സേവനങ്ങൾ ഉപയോഗിക്കുന്നു. പരസ്യങ്ങൾ നൽകുന്നതിനും ആപ്പ് സ്ഥിരത മെച്ചപ്പെടുത്തുന്നതിനും ഈ സേവനങ്ങൾ നിങ്ങളുടെ ഉപകരണത്തിന്റെ പരസ്യ ഐഡി ഉൾപ്പെടെയുള്ള അജ്ഞാത ഡാറ്റ ശേഖരിച്ചേക്കാം.',
    },
  };
}
